window.QBANK = window.QBANK || {};
window.QBANK["sma-matematika"] = {
  level: "SMA", subject: "Matematika", duration: 900,
  questions: [
    { q: "Diketahui $f(x) = 2x + 3$ dan $g(x) = x^2 - 1$. Nilai $(f \\circ g)(2)$ adalah ...", options: ["6", "9", "11", "7"], answer: 1, solution: "Langkah 1: $(f \\circ g)(2) = f(g(2))$, jadi hitung dulu $g(2) = 2^2 - 1 = 4 - 1 = 3$. Langkah 2: substitusi ke $f$: $f(3) = 2(3) + 3 = 6 + 3 = 9$. Langkah 3: jadi $(f \\circ g)(2) = 9$." },
    { q: "Nilai dari $\\sin 30^\\circ + \\cos 60^\\circ$ adalah ...", options: ["$\\frac{1}{2}$", "$\\sqrt{3}$", "$1$", "$0$"], answer: 2, solution: "Langkah 1: ingat sudut istimewa, $\\sin 30^\\circ = \\frac{1}{2}$. Langkah 2: $\\cos 60^\\circ = \\frac{1}{2}$. Langkah 3: jumlahkan, $\\frac{1}{2} + \\frac{1}{2} = 1$." },
    { q: "$\\lim_{x \\to 2} \\frac{x^2 - 4}{x - 2} = \\dots$", options: ["2", "0", "tidak ada", "4"], answer: 3, solution: "Langkah 1: substitusi langsung menghasilkan bentuk tak tentu $\\frac{0}{0}$. Langkah 2: faktorkan pembilang, $x^2 - 4 = (x-2)(x+2)$. Langkah 3: coret faktor $(x-2)$ pada pembilang dan penyebut, tersisa $\\lim_{x \\to 2}(x+2)$. Langkah 4: substitusi $x = 2$ diperoleh $2 + 2 = 4$." },
    { q: "Sebuah dadu dilempar sekali. Peluang muncul mata dadu bilangan prima adalah ...", options: ["$\\frac{1}{3}$", "$\\frac{1}{2}$", "$\\frac{2}{3}$", "$\\frac{1}{6}$"], answer: 1, solution: "Langkah 1: mata dadu bilangan prima adalah $\\{2, 3, 5\\}$, ada 3 kejadian. Langkah 2: total kemungkinan mata dadu ada 6. Langkah 3: peluang $= \\frac{\\text{kejadian}}{\u200b\\text{total}} = \\frac{3}{6} = \\frac{1}{2}$." },
    { q: "Nilai minimum fungsi $f(x) = x^2 - 6x + 5$ adalah ...", options: ["$-5$", "$4$", "$-4$", "$5$"], answer: 2, solution: "Langkah 1: karena $a = 1 > 0$, parabola terbuka ke atas sehingga punya nilai minimum di titik puncak. Langkah 2: sumbu simetri $x_p = -\\frac{b}{2a} = -\\frac{-6}{2(1)} = 3$. Langkah 3: substitusi, $f(3) = 3^2 - 6(3) + 5 = 9 - 18 + 5 = -4$. Jadi nilai minimumnya $-4$." },
    { q: "Nilai dari $\\tan 45^\\circ \\times \\cos 60^\\circ$ adalah ...", options: ["$1$", "$\\frac{\\sqrt{3}}{2}$", "$2$", "$\\frac{1}{2}$"], answer: 3, solution: "Langkah 1: $\\tan 45^\\circ = 1$. Langkah 2: $\\cos 60^\\circ = \\frac{1}{2}$. Langkah 3: kalikan, $1 \\times \\frac{1}{2} = \\frac{1}{2}$." },
    { q: "$\\lim_{x \\to 0} \\frac{\\sin 3x}{x} = \\dots$", options: ["$3$", "$0$", "$1$", "$\\infty$"], answer: 0, solution: "Langkah 1: gunakan limit trigonometri dasar $\\lim_{x \\to 0} \\frac{\\sin ax}{x} = a$. Langkah 2: pada soal ini $a = 3$. Langkah 3: jadi hasilnya $3$." },
    { q: "Dua koin dilempar bersamaan. Peluang keduanya muncul gambar (G) adalah ...", options: ["$\\frac{3}{4}$", "$\\frac{1}{2}$", "$1$", "$\\frac{1}{4}$"], answer: 3, solution: "Langkah 1: peluang satu koin muncul gambar $= \\frac{1}{2}$. Langkah 2: dua pelemparan adalah kejadian saling bebas. Langkah 3: kalikan peluangnya, $\\frac{1}{2} \\times \\frac{1}{2} = \\frac{1}{4}$." },
    { q: "Jika $f(x) = 3x - 2$, maka $f^{-1}(x) = \\dots$", options: ["$\\frac{x-2}{3}$", "$\\frac{x+2}{3}$", "$3x + 2$", "$\\frac{x}{3} - 2$"], answer: 1, solution: "Langkah 1: misalkan $y = 3x - 2$. Langkah 2: tukar $x$ dan $y$ menjadi $x = 3y - 2$. Langkah 3: selesaikan untuk $y$: $3y = x + 2$, sehingga $y = \\frac{x+2}{3}$. Jadi $f^{-1}(x) = \\frac{x+2}{3}$." },
    { q: "Jika $\\sin x = \\frac{3}{5}$ dengan $x$ sudut lancip, maka $\\cos x = \\dots$", options: ["$-\\frac{4}{5}$", "$\\frac{3}{4}$", "$\\frac{5}{4}$", "$\\frac{4}{5}$"], answer: 3, solution: "Langkah 1: gunakan identitas $\\sin^2 x + \\cos^2 x = 1$. Langkah 2: $\\cos^2 x = 1 - (\\frac{3}{5})^2 = 1 - \\frac{9}{25} = \\frac{16}{25}$. Langkah 3: karena $x$ sudut lancip, $\\cos x$ positif, jadi $\\cos x = \\sqrt{\\frac{16}{25}} = \\frac{4}{5}$." },
    { q: "Nilai dari $2^3 \\times 2^4$ adalah ...", options: ["$2^{12}$", "$2^7$", "$2$", "$4^7$"], answer: 1, solution: "Langkah 1: gunakan sifat eksponen $a^m \\times a^n = a^{m+n}$. Langkah 2: $2^3 \\times 2^4 = 2^{3+4} = 2^7$. Langkah 3: jadi hasilnya $2^7$. (Catatan: pangkatnya dijumlahkan, bukan dikalikan.)" },
    { q: "Nilai dari ${}^2\\log 32$ adalah ...", options: ["$4$", "$6$", "$5$", "$16$"], answer: 2, solution: "Langkah 1: ${}^2\\log 32 = n$ artinya $2^n = 32$. Langkah 2: karena $2^5 = 32$, maka $n = 5$. Langkah 3: jadi ${}^2\\log 32 = 5$." },
    { q: "Nilai dari $5^{-2}$ adalah ...", options: ["$-25$", "$\\frac{1}{25}$", "$-10$", "$\\frac{1}{10}$"], answer: 1, solution: "Langkah 1: gunakan sifat $a^{-n} = \\frac{1}{a^n}$. Langkah 2: $5^{-2} = \\frac{1}{5^2} = \\frac{1}{25}$. Langkah 3: jadi hasilnya $\\frac{1}{25}$." },
    { q: "Nilai dari ${}^3\\log 9 + {}^3\\log 3$ adalah ...", options: ["$3$", "$2$", "$5$", "$27$"], answer: 0, solution: "Langkah 1: gunakan sifat ${}^a\\log x + {}^a\\log y = {}^a\\log (x \\times y)$. Langkah 2: ${}^3\\log 9 + {}^3\\log 3 = {}^3\\log (9 \\times 3) = {}^3\\log 27$. Langkah 3: karena $3^3 = 27$, maka hasilnya $3$." },
    { q: "Diketahui $f(x) = x + 1$ dan $g(x) = 2x$. Nilai $(g \\circ f)(3)$ adalah ...", options: ["$7$", "$8$", "$6$", "$10$"], answer: 1, solution: "Langkah 1: $(g \\circ f)(3) = g(f(3))$, hitung dulu $f(3) = 3 + 1 = 4$. Langkah 2: substitusi ke $g$: $g(4) = 2(4) = 8$. Langkah 3: jadi $(g \\circ f)(3) = 8$. (Catatan: urutan komposisi tidak boleh dibalik.)" },
    { q: "Jika $f(x) = 2x - 6$, maka $f^{-1}(x) = \\dots$", options: ["$\\frac{x-6}{2}$", "$2x + 6$", "$\\frac{x+6}{2}$", "$\\frac{x}{2} + 6$"], answer: 2, solution: "Langkah 1: misalkan $y = 2x - 6$. Langkah 2: tukar $x$ dan $y$ menjadi $x = 2y - 6$. Langkah 3: selesaikan untuk $y$: $2y = x + 6$, sehingga $y = \\frac{x+6}{2}$. Jadi $f^{-1}(x) = \\frac{x+6}{2}$." },
    { q: "Nilai dari $\\cos 150^\\circ$ adalah ...", options: ["$\\frac{\\sqrt{3}}{2}$", "$-\\frac{1}{2}$", "$-\\frac{\\sqrt{3}}{2}$", "$\\frac{1}{2}$"], answer: 2, solution: "Langkah 1: $150^\\circ$ berada di kuadran II, di mana nilai cosinus negatif. Langkah 2: $\\cos 150^\\circ = -\\cos(180^\\circ - 150^\\circ) = -\\cos 30^\\circ$. Langkah 3: $\\cos 30^\\circ = \\frac{\\sqrt{3}}{2}$, jadi hasilnya $-\\frac{\\sqrt{3}}{2}$." },
    { q: "Jika $\\tan x = \\frac{4}{3}$ dengan $x$ sudut lancip, maka $\\sin x = \\dots$", options: ["$\\frac{3}{5}$", "$\\frac{5}{4}$", "$\\frac{4}{5}$", "$\\frac{3}{4}$"], answer: 2, solution: "Langkah 1: $\\tan x = \\frac{\\text{depan}}{\\text{samping}} = \\frac{4}{3}$, jadi sisi depan $= 4$ dan sisi samping $= 3$. Langkah 2: sisi miring $= \\sqrt{4^2 + 3^2} = \\sqrt{25} = 5$. Langkah 3: $\\sin x = \\frac{\\text{depan}}{\\text{miring}} = \\frac{4}{5}$." },
    { q: "Diketahui vektor $\\vec{a} = (3, 4)$. Panjang vektor $\\vec{a}$ adalah ...", options: ["$7$", "$5$", "$25$", "$\\sqrt{7}$"], answer: 1, solution: "Langkah 1: gunakan rumus panjang vektor $|\\vec{a}| = \\sqrt{x^2 + y^2}$. Langkah 2: $|\\vec{a}| = \\sqrt{3^2 + 4^2} = \\sqrt{9 + 16} = \\sqrt{25}$. Langkah 3: jadi panjangnya $5$." },
    { q: "Diketahui $\\vec{a} = (1, 2)$ dan $\\vec{b} = (3, -1)$. Hasil $\\vec{a} + \\vec{b}$ adalah ...", options: ["$(4, 3)$", "$(4, 1)$", "$(2, -3)$", "$(3, -2)$"], answer: 1, solution: "Langkah 1: jumlahkan komponen yang bersesuaian: $(1+3, 2+(-1))$. Langkah 2: $= (4, 1)$. Langkah 3: jadi $\\vec{a} + \\vec{b} = (4, 1)$." },
    { q: "$\\lim_{x \\to 3} \\frac{x^2 - 9}{x - 3} = \\dots$", options: ["$3$", "$0$", "$6$", "$9$"], answer: 2, solution: "Langkah 1: substitusi langsung menghasilkan bentuk tak tentu $\\frac{0}{0}$. Langkah 2: faktorkan pembilang, $x^2 - 9 = (x-3)(x+3)$. Langkah 3: coret faktor $(x-3)$, tersisa $\\lim_{x \\to 3}(x+3) = 3 + 3 = 6$." },
    { q: "$\\lim_{x \\to \\infty} \\frac{2x^2 + 1}{x^2 - 3} = \\dots$", options: ["$0$", "$2$", "$\\infty$", "$1$"], answer: 1, solution: "Langkah 1: untuk limit tak hingga fungsi rasional, bandingkan pangkat tertinggi pembilang dan penyebut. Langkah 2: keduanya berpangkat $2$ (sama), maka limit $=$ perbandingan koefisien $x^2$. Langkah 3: $\\frac{2}{1} = 2$." },
    { q: "Jika $f(x) = 3x^2 - 5x + 2$, maka $f'(x) = \\dots$", options: ["$6x - 5$", "$6x^2 - 5$", "$3x - 5$", "$6x + 5$"], answer: 0, solution: "Langkah 1: gunakan aturan turunan $\\frac{d}{dx}(ax^n) = n \\cdot ax^{n-1}$. Langkah 2: turunan $3x^2$ adalah $6x$, turunan $-5x$ adalah $-5$, turunan konstanta $2$ adalah $0$. Langkah 3: jadi $f'(x) = 6x - 5$." },
    { q: "Fungsi $f(x) = x^2 - 4x + 1$ mencapai nilai minimum pada $x = \\dots$", options: ["$-2$", "$2$", "$4$", "$1$"], answer: 1, solution: "Langkah 1: syarat stasioner $f'(x) = 0$. Langkah 2: $f'(x) = 2x - 4$, sehingga $2x - 4 = 0$ dan $x = 2$. Langkah 3: karena $f''(x) = 2 > 0$, titik ini adalah minimum. Jadi minimum pada $x = 2$." },
    { q: "Sebuah bola dilempar ke atas dengan ketinggian $h(t) = 20t - 5t^2$ meter ($t$ dalam sekon). Tinggi maksimum bola adalah ...", options: ["$15$ m", "$20$ m", "$25$ m", "$40$ m"], answer: 1, solution: "Langkah 1: tinggi maksimum saat kecepatan nol, yaitu $h'(t) = 0$. Langkah 2: $h'(t) = 20 - 10t = 0$, sehingga $t = 2$ sekon. Langkah 3: $h(2) = 20(2) - 5(2^2) = 40 - 20 = 20$ meter." },
    { q: "$\\int (4x + 3)\\,dx = \\dots$", options: ["$2x^2 + 3x + C$", "$4x^2 + 3x + C$", "$2x^2 + C$", "$x^4 + 3x + C$"], answer: 0, solution: "Langkah 1: gunakan $\\int x^n\\,dx = \\frac{1}{n+1}x^{n+1} + C$. Langkah 2: $\\int 4x\\,dx = 4 \\cdot \\frac{x^2}{2} = 2x^2$ dan $\\int 3\\,dx = 3x$. Langkah 3: jadi hasilnya $2x^2 + 3x + C$." },
    { q: "$\\int_0^2 3x^2\\,dx = \\dots$", options: ["$6$", "$8$", "$12$", "$4$"], answer: 1, solution: "Langkah 1: tentukan antiturunan $3x^2$, yaitu $x^3$. Langkah 2: evaluasi pada batas $0$ sampai $2$: $[x^3]_0^2 = 2^3 - 0^3$. Langkah 3: $= 8 - 0 = 8$." },
    { q: "Rata-rata dari data $4, 6, 5, 7, 8$ adalah ...", options: ["$5$", "$6$", "$7$", "$5{,}5$"], answer: 1, solution: "Langkah 1: jumlahkan semua data, $4 + 6 + 5 + 7 + 8 = 30$. Langkah 2: banyak data $= 5$. Langkah 3: rata-rata $= \\frac{30}{5} = 6$." },
    { q: "Median dari data $3, 7, 5, 9, 1$ adalah ...", options: ["$3$", "$5$", "$7$", "$9$"], answer: 1, solution: "Langkah 1: urutkan data terlebih dahulu: $1, 3, 5, 7, 9$. Langkah 2: median adalah nilai tengah data yang sudah terurut. Langkah 3: nilai tengahnya adalah $5$." },
    { q: "Hasil dari $\\begin{pmatrix}1 & 2\\\\3 & 4\\end{pmatrix} + \\begin{pmatrix}5 & 6\\\\7 & 8\\end{pmatrix}$ adalah ...", options: ["$\\begin{pmatrix}6 & 8\\\\10 & 12\\end{pmatrix}$", "$\\begin{pmatrix}5 & 12\\\\21 & 32\\end{pmatrix}$", "$\\begin{pmatrix}6 & 7\\\\8 & 9\\end{pmatrix}$", "$\\begin{pmatrix}4 & 4\\\\4 & 4\\end{pmatrix}$"], answer: 0, solution: "Langkah 1: penjumlahan matriks dilakukan pada entri yang bersesuaian. Langkah 2: $\\begin{pmatrix}1+5 & 2+6\\\\3+7 & 4+8\\end{pmatrix} = \\begin{pmatrix}6 & 8\\\\10 & 12\\end{pmatrix}$. Langkah 3: jadi hasilnya $\\begin{pmatrix}6 & 8\\\\10 & 12\\end{pmatrix}$." },
    { q: "Banyak susunan plat nomor yang terdiri dari $2$ huruf diikuti $2$ angka (huruf dan angka boleh berulang) adalah ...", options: ["$6.760$", "$67.600$", "$676.000$", "$2.600$"], answer: 1, solution: "Langkah 1: gunakan aturan perkalian (aturan pencacahan). Langkah 2: tiap posisi huruf ada $26$ pilihan dan tiap posisi angka ada $10$ pilihan. Langkah 3: karena boleh berulang, banyak susunan $= 26 \\times 26 \\times 10 \\times 10 = 676 \\times 100 = 67600$. (Catatan: kalau tidak boleh berulang, pilihannya $26 \\times 25 \\times 10 \\times 9$.)" },
    { q: "Dari $7$ orang akan dipilih $4$ orang untuk duduk berjajar sebagai panitia inti (urutan diperhatikan). Banyak susunan yang mungkin adalah ...", options: ["$28$", "$840$", "$35$", "$210$"], answer: 1, solution: "Langkah 1: urutan diperhatikan, jadi gunakan permutasi ${}^7P_4$. Langkah 2: ${}^7P_4 = 7 \\times 6 \\times 5 \\times 4$. Langkah 3: $7 \\times 6 \\times 5 \\times 4 = 840$. (Catatan: kalau urutan tidak diperhatikan, gunakan kombinasi.)" },
    { q: "Banyak susunan huruf berbeda yang dapat dibentuk dari kata \"MATEMATIKA\" adalah ...", options: ["$151.200$", "$3.628.800$", "$604.800$", "$75.600$"], answer: 0, solution: "Langkah 1: kata MATEMATIKA terdiri dari $10$ huruf dengan huruf berulang: M ada $2$, A ada $3$, T ada $2$. Langkah 2: gunakan permutasi dengan unsur sama, $\\frac{10!}{2! \\times 3! \\times 2!}$. Langkah 3: $\\frac{3628800}{2 \\times 6 \\times 2} = \\frac{3628800}{24} = 151200$. (Catatan: $10! = 3628800$ hanya benar jika semua huruf berbeda.)" },
    { q: "Dari $8$ siswa akan dipilih $3$ orang untuk mengikuti lomba (urutan tidak diperhatikan). Banyak cara memilih adalah ...", options: ["$24$", "$336$", "$56$", "$112$"], answer: 2, solution: "Langkah 1: urutan tidak diperhatikan, jadi gunakan kombinasi ${}^8C_3$. Langkah 2: ${}^8C_3 = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1}$. Langkah 3: $= \\frac{336}{6} = 56$. (Catatan: $336$ adalah hasil permutasi ${}^8P_3$, salah karena urutan tidak diperhatikan.)" },
    { q: "Dari $4$ calon akan dibentuk tim yang terdiri dari $2$ orang. Banyak tim berbeda yang dapat dibentuk adalah ...", options: ["$12$", "$8$", "$6$", "$4$"], answer: 2, solution: "Langkah 1: urutan anggota tim tidak diperhatikan, gunakan kombinasi ${}^4C_2$. Langkah 2: ${}^4C_2 = \\frac{4 \\times 3}{2 \\times 1}$. Langkah 3: $= \\frac{12}{2} = 6$. (Catatan: $12$ adalah permutasi, keliru karena susunan tim yang sama dihitung dua kali.)" },
    { q: "Dari setumpuk kartu bridge diambil sebuah kartu secara acak. Peluang terambilnya kartu As adalah ...", options: ["$\\frac{1}{4}$", "$\\frac{1}{13}$", "$\\frac{1}{52}$", "$\\frac{4}{13}$"], answer: 1, solution: "Langkah 1: kartu As ada $4$ buah, total kartu $52$. Langkah 2: peluang $= \\frac{\\text{kejadian yang diinginkan}}{\\text{seluruh kejadian}} = \\frac{4}{52}$. Langkah 3: sederhanakan, $\\frac{4}{52} = \\frac{1}{13}$." },
    { q: "Sebuah dadu dilempar sekali. Peluang muncul mata dadu lebih dari $4$ adalah ...", options: ["$\\frac{1}{2}$", "$\\frac{2}{3}$", "$\\frac{1}{3}$", "$\\frac{1}{6}$"], answer: 2, solution: "Langkah 1: mata dadu lebih dari $4$ adalah $\\{5, 6\\}$, ada $2$ kejadian. Langkah 2: total kemungkinan mata dadu ada $6$. Langkah 3: peluang $= \\frac{2}{6} = \\frac{1}{3}$." },
    { q: "Sebuah kotak berisi $3$ bola merah dan $2$ bola putih. Jika diambil sebuah bola secara acak, peluang terambilnya bola merah adalah ...", options: ["$\\frac{2}{5}$", "$\\frac{3}{5}$", "$\\frac{1}{3}$", "$\\frac{3}{2}$"], answer: 1, solution: "Langkah 1: bola merah ada $3$, total bola $= 3 + 2 = 5$. Langkah 2: peluang $= \\frac{\\text{bola merah}}{\\text{total bola}} = \\frac{3}{5}$. Langkah 3: jadi peluangnya $\\frac{3}{5}$. (Catatan: $\\frac{3}{2}$ lebih dari $1$, mustahil untuk sebuah peluang.)" },
    { q: "Seorang pedagang membuat $x$ roti A dan $y$ roti B. Roti A memerlukan $100$ g tepung dan $50$ g gula, roti B memerlukan $200$ g tepung dan $30$ g gula. Tersedia $6$ kg tepung dan $1{,}8$ kg gula. Model matematika yang tepat adalah ...", options: ["$x + 2y \\le 60$; $5x + 3y \\le 180$; $x \\ge 0$; $y \\ge 0$", "$2x + y \\le 60$; $3x + 5y \\le 180$; $x \\ge 0$; $y \\ge 0$", "$x + 2y \\ge 60$; $5x + 3y \\ge 180$; $x \\ge 0$; $y \\ge 0$", "$x + y \\le 60$; $x + y \\le 180$; $x \\ge 0$; $y \\ge 0$"], answer: 0, solution: "Langkah 1: samakan satuannya, tepung $6$ kg $= 6000$ g dan gula $1{,}8$ kg $= 1800$ g. Langkah 2: kendala tepung: $100x + 200y \\le 6000$, sederhanakan menjadi $x + 2y \\le 60$. Langkah 3: kendala gula: $50x + 30y \\le 1800$, sederhanakan menjadi $5x + 3y \\le 180$, dengan $x \\ge 0$ dan $y \\ge 0$." },
    { q: "Nilai maksimum dari $f(x, y) = 3x + 4y$ dengan kendala $x + y \\le 8$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$24$", "$20$", "$32$", "$28$"], answer: 2, solution: "Langkah 1: daerah penyelesaian berupa segitiga dengan titik pojok $(0,0)$, $(8,0)$, dan $(0,8)$. Langkah 2: substitusi tiap titik pojok ke $f$: $f(0,0) = 0$, $f(8,0) = 24$, $f(0,8) = 32$. Langkah 3: nilai terbesar adalah $32$ pada titik $(0, 8)$." },
    { q: "Nilai minimum dari $f(x, y) = 3x + 2y$ dengan kendala $x + 2y \\ge 8$, $2x + y \\ge 10$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$20$", "$24$", "$16$", "$12$"], answer: 2, solution: "Langkah 1: cari titik pojok daerah penyelesaian. Perpotongan $x + 2y = 8$ dan $2x + y = 10$ menghasilkan $x = 4$, $y = 2$. Titik pojok lain: $(0, 10)$ dan $(8, 0)$. Langkah 2: substitusi ke $f$: $f(4,2) = 12 + 4 = 16$, $f(0,10) = 20$, $f(8,0) = 24$. Langkah 3: nilai terkecil adalah $16$ pada titik $(4, 2)$." },
    { q: "Nilai maksimum dari $f(x, y) = x + 3y$ dengan kendala $x + y \\le 6$, $2x + y \\le 8$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$14$", "$18$", "$12$", "$16$"], answer: 1, solution: "Langkah 1: tentukan titik pojok. Perpotongan $x + y = 6$ dan $2x + y = 8$ menghasilkan $x = 2$, $y = 4$. Titik pojok lain: $(0,0)$, $(4,0)$, $(0,6)$. Langkah 2: $f(0,0) = 0$, $f(4,0) = 4$, $f(0,6) = 18$, $f(2,4) = 14$. Langkah 3: nilai maksimum adalah $18$ pada titik $(0, 6)$." },
    { q: "Diketahui kubus $ABCD.EFGH$ dengan panjang rusuk $8$ cm. Jarak titik $B$ ke garis $AC$ adalah ...", options: ["$8$ cm", "$4\\sqrt{2}$ cm", "$8\\sqrt{2}$ cm", "$4$ cm"], answer: 1, solution: "Langkah 1: $AC$ adalah diagonal sisi alas; proyeksi titik $B$ ke garis $AC$ jatuh tepat di tengah-tengah $AC$ (titik $O$). Langkah 2: segitiga $ABO$ siku-siku di $O$ dengan $AB = 8$ cm dan $AO = \\frac{1}{2} \\cdot 8\\sqrt{2} = 4\\sqrt{2}$ cm. Langkah 3: $BO = \\sqrt{AB^2 - AO^2} = \\sqrt{64 - 32} = \\sqrt{32} = 4\\sqrt{2}$ cm." },
    { q: "Diketahui kubus $ABCD.EFGH$ dengan panjang rusuk $6$ cm. Jarak titik $A$ ke bidang $BDE$ adalah ...", options: ["$2\\sqrt{3}$ cm", "$3\\sqrt{2}$ cm", "$6$ cm", "$\\sqrt{3}$ cm"], answer: 0, solution: "Langkah 1: letakkan kubus pada koordinat $A(0,0,0)$, $B(6,0,0)$, $D(0,6,0)$, $E(0,0,6)$. Bidang $BDE$ berpersamaan $\\frac{x}{6} + \\frac{y}{6} + \\frac{z}{6} = 1$ atau $x + y + z - 6 = 0$. Langkah 2: jarak titik ke bidang $= \\frac{|0 + 0 + 0 - 6|}{\\sqrt{1^2 + 1^2 + 1^2}} = \\frac{6}{\\sqrt{3}}$. Langkah 3: rasionalkan, $\\frac{6}{\\sqrt{3}} = 2\\sqrt{3}$ cm." },
    { q: "Diketahui kubus $ABCD.EFGH$. Besar sudut antara garis $AH$ dan bidang $ABCD$ adalah ...", options: ["$30^\\circ$", "$45^\\circ$", "$60^\\circ$", "$90^\\circ$"], answer: 1, solution: "Langkah 1: proyeksi garis $AH$ pada bidang alas $ABCD$ adalah garis $AD$. Langkah 2: sudut antara $AH$ dan bidang $ABCD$ sama dengan sudut $HAD$. Langkah 3: segitiga $ADH$ siku-siku di $D$ dengan $AD = DH$ (rusuk kubus), jadi segitiga siku-siku sama kaki dan sudut $HAD = 45^\\circ$." },
    { q: "Diketahui kubus $ABCD.EFGH$ dengan panjang rusuk $4$ cm. Jarak titik $G$ ke garis $AC$ adalah ...", options: ["$4\\sqrt{2}$ cm", "$2\\sqrt{2}$ cm", "$4$ cm", "$8$ cm"], answer: 2, solution: "Langkah 1: proyeksi ortogonal titik $G$ pada bidang alas adalah titik $C$, dan titik $C$ terletak pada garis $AC$. Langkah 2: karena $GC$ tegak lurus bidang $ABCD$, maka $GC$ juga tegak lurus garis $AC$ yang terletak pada bidang tersebut. Langkah 3: jadi kaki tegak lurus dari $G$ ke garis $AC$ adalah titik $C$ sendiri, dan jaraknya $= GC = 4$ cm." },
    { q: "Titik puncak parabola $f(x) = x^2 + 4x + 3$ adalah ...", options: ["$(2, 1)$", "$(-2, -1)$", "$(-2, 1)$", "$(2, -1)$"], answer: 1, solution: "Langkah 1: absis titik puncak $x_p = -\\frac{b}{2a} = -\\frac{4}{2(1)} = -2$. Langkah 2: ordinatnya $y_p = f(-2) = (-2)^2 + 4(-2) + 3 = 4 - 8 + 3 = -1$. Langkah 3: jadi titik puncaknya $(-2, -1)$. (Catatan: karena $a > 0$, ini titik minimum.)" },
    { q: "Sumbu simetri grafik fungsi $f(x) = 2x^2 + 10x - 3$ adalah ...", options: ["$x = 5$", "$x = -\\frac{5}{2}$", "$x = \\frac{5}{2}$", "$x = -5$"], answer: 1, solution: "Langkah 1: gunakan rumus sumbu simetri $x = -\\frac{b}{2a}$. Langkah 2: dengan $a = 2$ dan $b = 10$, diperoleh $x = -\\frac{10}{2(2)} = -\\frac{10}{4}$. Langkah 3: sederhanakan, $x = -\\frac{5}{2}$." },
    { q: "Agar persamaan $x^2 - 4x + k = 0$ mempunyai akar-akar kembar (sama), nilai $k$ adalah ...", options: ["$-4$", "$2$", "$4$", "$8$"], answer: 2, solution: "Langkah 1: syarat akar kembar adalah diskriminan $D = 0$. Langkah 2: $D = b^2 - 4ac = (-4)^2 - 4(1)(k) = 16 - 4k$. Langkah 3: $16 - 4k = 0$, sehingga $4k = 16$ dan $k = 4$." },
    { q: "Keuntungan (dalam juta rupiah) sebuah usaha dimodelkan $P(x) = -2x^2 + 40x - 100$, dengan $x$ banyak barang (dalam ratusan unit). Keuntungan maksimum yang dapat diperoleh adalah ...", options: ["$50$ juta", "$100$ juta", "$200$ juta", "$300$ juta"], answer: 1, solution: "Langkah 1: karena $a = -2 < 0$, parabola terbuka ke bawah sehingga nilai maksimum ada di titik puncak. Langkah 2: $x_p = -\\frac{b}{2a} = -\\frac{40}{2(-2)} = 10$. Langkah 3: $P(10) = -2(10)^2 + 40(10) - 100 = -200 + 400 - 100 = 100$. Jadi keuntungan maksimum $100$ juta rupiah." },
    { q: "Nilai dari $2^5 \\times 2^2$ adalah ...", options: ["$2^7$", "$2^{10}$", "$4^7$", "$2^5$"], answer: 0, solution: "1. Gunakan sifat $a^m \\times a^n = a^{m+n}$. 2. $2^5 \\times 2^2 = 2^{5+2} = 2^7$. 3. Jadi jawabannya $2^7$." },
    { q: "Nilai dari $(3^2)^4$ adalah ...", options: ["$3^6$", "$3^8$", "$3^{16}$", "$9^6$"], answer: 1, solution: "1. Gunakan sifat $(a^m)^n = a^{m \\times n}$. 2. $(3^2)^4 = 3^{2 \\times 4} = 3^8$. 3. Jadi jawabannya $3^8$." },
    { q: "Nilai dari $\\frac{5^6}{5^4}$ adalah ...", options: ["$5^{24}$", "$5^{10}$", "$5^2$", "$5^4$"], answer: 2, solution: "1. Gunakan sifat $\\frac{a^m}{a^n} = a^{m-n}$. 2. $\\frac{5^6}{5^4} = 5^{6-4} = 5^2 = 25$. 3. Jadi jawabannya $5^2$." },
    { q: "Nilai dari $4^{-2}$ adalah ...", options: ["$-16$", "$16$", "$-\\frac{1}{16}$", "$\\frac{1}{16}$"], answer: 3, solution: "1. Gunakan sifat $a^{-n} = \\frac{1}{a^n}$. 2. $4^{-2} = \\frac{1}{4^2} = \\frac{1}{16}$. 3. Jadi jawabannya $\\frac{1}{16}$." },
    { q: "Nilai dari $\\sqrt[3]{27 \\times 8}$ adalah ...", options: ["$6$", "$9$", "$12$", "$3$"], answer: 0, solution: "1. Kalikan dahulu: $27 \\times 8 = 216$. 2. $\\sqrt[3]{216} = 6$ karena $6^3 = 216$. 3. Jadi jawabannya $6$." },
    { q: "Nilai dari $8^{\\frac{2}{3}}$ adalah ...", options: ["$2$", "$4$", "$8$", "$16$"], answer: 1, solution: "1. $8^{\\frac{2}{3}} = (\\sqrt[3]{8})^2$. 2. $\\sqrt[3]{8} = 2$, lalu $2^2 = 4$. 3. Jadi jawabannya $4$." },
    { q: "Nilai dari $(2^{-3} \\times 2^5)^2$ adalah ...", options: ["$4$", "$64$", "$16$", "$2$"], answer: 2, solution: "1. Sederhanakan dalam kurung: $2^{-3} \\times 2^5 = 2^2 = 4$. 2. Kuadratkan: $4^2 = 16$. 3. Jadi jawabannya $16$." },
    { q: "Nilai dari $\\sqrt{50} + \\sqrt{18}$ adalah ...", options: ["$5\\sqrt{2}$", "$\\sqrt{68}$", "$68$", "$8\\sqrt{2}$"], answer: 3, solution: "1. $\\sqrt{50} = 5\\sqrt{2}$ dan $\\sqrt{18} = 3\\sqrt{2}$. 2. Jumlahkan: $5\\sqrt{2} + 3\\sqrt{2} = 8\\sqrt{2}$. 3. Jadi jawabannya $8\\sqrt{2}$." },
    { q: "Nilai dari ${}^2\\log 64$ adalah ...", options: ["$32$", "$6$", "$8$", "$12$"], answer: 1, solution: "1. Cari $n$ sehingga $2^n = 64$. 2. Karena $2^6 = 64$, maka ${}^2\\log 64 = 6$. 3. Jadi jawabannya $6$." },
    { q: "Nilai dari ${}^5\\log 125 - {}^5\\log 5$ adalah ...", options: ["$3$", "$25$", "$2$", "$1$"], answer: 2, solution: "1. ${}^5\\log 125 = 3$ dan ${}^5\\log 5 = 1$. 2. Kurangkan: $3 - 1 = 2$. 3. Jadi jawabannya $2$." },
    { q: "Nilai dari ${}^4\\log 8 + {}^4\\log 2$ adalah ...", options: ["$10$", "$3$", "$8$", "$2$"], answer: 3, solution: "1. Gunakan sifat ${}^a\\log b + {}^a\\log c = {}^a\\log(bc)$. 2. ${}^4\\log 8 + {}^4\\log 2 = {}^4\\log 16 = 2$. 3. Jadi jawabannya $2$." },
    { q: "Nilai dari ${}^2\\log (4^3)$ adalah ...", options: ["$6$", "$12$", "$5$", "$8$"], answer: 0, solution: "1. Gunakan sifat ${}^a\\log(b^n) = n \\cdot {}^a\\log b$. 2. ${}^2\\log (4^3) = 3 \\cdot {}^2\\log 4 = 3 \\cdot 2 = 6$. 3. Jadi jawabannya $6$." },
    { q: "Jika ${}^2\\log x = 4$, maka nilai $x$ adalah ...", options: ["$8$", "$16$", "$2$", "$64$"], answer: 1, solution: "1. ${}^2\\log x = 4$ berarti $x = 2^4$. 2. $2^4 = 16$. 3. Jadi nilai $x = 16$." },
    { q: "Jika ${}^3\\log x = -2$, maka nilai $x$ adalah ...", options: ["$-9$", "$9$", "$\\frac{1}{9}$", "$-\\frac{1}{9}$"], answer: 2, solution: "1. ${}^3\\log x = -2$ berarti $x = 3^{-2}$. 2. $3^{-2} = \\frac{1}{9}$. 3. Jadi nilai $x = \\frac{1}{9}$." },
    { q: "Nilai dari ${}^2\\log \\sqrt{8}$ adalah ...", options: ["$3$", "$2$", "$\\frac{1}{2}$", "$\\frac{3}{2}$"], answer: 3, solution: "1. $\\sqrt{8} = 2^{\\frac{3}{2}}$. 2. ${}^2\\log 2^{\\frac{3}{2}} = \\frac{3}{2}$. 3. Jadi jawabannya $\\frac{3}{2}$." },
    { q: "Jika ${}^5\\log (x-2) = 2$, maka nilai $x$ adalah ...", options: ["$27$", "$10$", "$25$", "$12$"], answer: 0, solution: "1. ${}^5\\log (x-2) = 2$ berarti $x - 2 = 5^2 = 25$. 2. Maka $x = 25 + 2 = 27$. 3. Jadi nilai $x = 27$." },
    { q: "Diketahui $f(x) = 3x-1$ dan $g(x) = x^2+2$. Nilai $(f \\circ g)(2)$ adalah ...", options: ["$27$", "$11$", "$17$", "$35$"], answer: 2, solution: "1. Hitung $g(2) = 2^2 + 2 = 6$. 2. Hitung $f(6) = 3(6) - 1 = 17$. 3. Jadi $(f \\circ g)(2) = 17$." },
    { q: "Diketahui $f(x) = 2x$ dan $g(x) = x+3$. Nilai $(f \\circ g)(4)$ adalah ...", options: ["$11$", "$24$", "$7$", "$14$"], answer: 3, solution: "1. Hitung $g(4) = 4 + 3 = 7$. 2. Hitung $f(7) = 2(7) = 14$. 3. Jadi $(f \\circ g)(4) = 14$." },
    { q: "Diketahui $f(x) = x^2$ dan $g(x) = 2x+1$. Rumus $(f \\circ g)(x)$ adalah ...", options: ["$4x^2+4x+1$", "$2x^2+1$", "$4x^2+1$", "$2x^2+2x+1$"], answer: 0, solution: "1. $(f \\circ g)(x) = f(g(x)) = (2x+1)^2$. 2. Jabarkan: $(2x+1)^2 = 4x^2+4x+1$. 3. Jadi $(f \\circ g)(x) = 4x^2+4x+1$." },
    { q: "Diketahui $f(x) = x-3$ dan $g(x) = x^2-1$. Rumus $(g \\circ f)(x)$ adalah ...", options: ["$x^2-9$", "$x^2-6x+8$", "$x^2-6x-1$", "$x^2+8$"], answer: 1, solution: "1. $(g \\circ f)(x) = g(f(x)) = (x-3)^2 - 1$. 2. Jabarkan: $x^2-6x+9-1 = x^2-6x+8$. 3. Jadi $(g \\circ f)(x) = x^2-6x+8$." },
    { q: "Diketahui $f(x) = 2x-5$ dan $g(x) = 3x+1$. Nilai $(f \\circ g)(-1)$ adalah ...", options: ["$-7$", "$1$", "$-9$", "$-4$"], answer: 2, solution: "1. Hitung $g(-1) = 3(-1)+1 = -2$. 2. Hitung $f(-2) = 2(-2)-5 = -9$. 3. Jadi $(f \\circ g)(-1) = -9$." },
    { q: "Diketahui $f(x) = x^2-3$ dan $g(x) = x+1$. Nilai $(g \\circ f)(3)$ adalah ...", options: ["$13$", "$10$", "$16$", "$7$"], answer: 3, solution: "1. Hitung $f(3) = 3^2-3 = 6$. 2. Hitung $g(6) = 6+1 = 7$. 3. Jadi $(g \\circ f)(3) = 7$." },
    { q: "Diketahui $f(x) = 4x+3$ dan $(f \\circ g)(x) = 8x-5$. Rumus $g(x)$ adalah ...", options: ["$2x-2$", "$x-2$", "$2x-8$", "$x-8$"], answer: 0, solution: "1. $(f \\circ g)(x) = 4g(x)+3 = 8x-5$. 2. Maka $4g(x) = 8x-8$, sehingga $g(x) = 2x-2$. 3. Jadi $g(x) = 2x-2$." },
    { q: "Diketahui $f(x) = x^2+1$ dan $g(x) = 2x-3$. Nilai $(f \\circ g)(1)$ adalah ...", options: ["$1$", "$2$", "$6$", "$-1$"], answer: 1, solution: "1. Hitung $g(1) = 2(1)-3 = -1$. 2. Hitung $f(-1) = (-1)^2+1 = 2$. 3. Jadi $(f \\circ g)(1) = 2$." },
    { q: "Invers dari fungsi $f(x) = 4x+5$ adalah ...", options: ["$\\frac{x+5}{4}$", "$4x-5$", "$\\frac{x}{4}-5$", "$\\frac{x-5}{4}$"], answer: 3, solution: "1. Misalkan $y = 4x+5$. 2. Selesaikan untuk $x$: $x = \\frac{y-5}{4}$. 3. Jadi $f^{-1}(x) = \\frac{x-5}{4}$." },
    { q: "Invers dari fungsi $f(x) = \\frac{x+3}{2}$ adalah ...", options: ["$2x-3$", "$\\frac{x-3}{2}$", "$2x+3$", "$\\frac{x+3}{2}$"], answer: 0, solution: "1. Misalkan $y = \\frac{x+3}{2}$. 2. Maka $2y = x+3$, sehingga $x = 2y-3$. 3. Jadi $f^{-1}(x) = 2x-3$." },
    { q: "Invers dari fungsi $f(x) = 5-2x$ adalah ...", options: ["$\\frac{x-5}{2}$", "$\\frac{5-x}{2}$", "$2x+5$", "$\\frac{5+x}{2}$"], answer: 1, solution: "1. Misalkan $y = 5-2x$. 2. Maka $2x = 5-y$, sehingga $x = \\frac{5-y}{2}$. 3. Jadi $f^{-1}(x) = \\frac{5-x}{2}$." },
    { q: "Diketahui $f(x) = x+2$ dan $g(x) = 3x-1$. Rumus $(f \\circ g)^{-1}(x)$ adalah ...", options: ["$\\frac{x+1}{3}$", "$3x+1$", "$\\frac{x-1}{3}$", "$\\frac{x}{3}-1$"], answer: 2, solution: "1. $(f \\circ g)(x) = (3x-1)+2 = 3x+1$. 2. Inversnya: misal $y = 3x+1$, maka $x = \\frac{y-1}{3}$. 3. Jadi $(f \\circ g)^{-1}(x) = \\frac{x-1}{3}$." },
    { q: "Diketahui $f(x) = 2x-7$. Nilai $f^{-1}(3)$ adalah ...", options: ["$-2$", "$13$", "$3$", "$5$"], answer: 3, solution: "1. Cari $x$ sehingga $f(x) = 3$, yaitu $2x-7 = 3$. 2. $2x = 10$, maka $x = 5$. 3. Jadi $f^{-1}(3) = 5$." },
    { q: "Diketahui $g(x) = x-4$ dan $h(x) = 2x+3$. Nilai $(g \\circ h)^{-1}(5)$ adalah ...", options: ["$3$", "$2$", "$8$", "$6$"], answer: 0, solution: "1. $(g \\circ h)(x) = (2x+3)-4 = 2x-1$. 2. Cari $x$ sehingga $2x-1 = 5$, maka $x = 3$. 3. Jadi $(g \\circ h)^{-1}(5) = 3$." },
    { q: "Nilai $\\lim_{x \\to 1} \\frac{x^2+3x-4}{x-1}$ adalah ...", options: ["$4$", "$5$", "$3$", "$6$"], answer: 1, solution: "1. Faktorkan: $\\frac{(x+4)(x-1)}{x-1} = x+4$. 2. Substitusi $x = 1$: $1+4 = 5$. 3. Jadi limitnya $5$." },
    { q: "Nilai $\\lim_{x \\to -2} \\frac{x^2-4}{x+2}$ adalah ...", options: ["$4$", "$0$", "$-4$", "$-2$"], answer: 2, solution: "1. Faktorkan: $\\frac{(x-2)(x+2)}{x+2} = x-2$. 2. Substitusi $x = -2$: $-2-2 = -4$. 3. Jadi limitnya $-4$." },
    { q: "Nilai $\\lim_{x \\to 3} \\frac{x^2-2x-3}{x-3}$ adalah ...", options: ["$3$", "$10$", "$0$", "$4$"], answer: 3, solution: "1. Faktorkan: $\\frac{(x-3)(x+1)}{x-3} = x+1$. 2. Substitusi $x = 3$: $3+1 = 4$. 3. Jadi limitnya $4$." },
    { q: "Nilai $\\lim_{x \\to 4} \\frac{\\sqrt{x}-2}{x-4}$ adalah ...", options: ["$\\frac{1}{4}$", "$4$", "$2$", "$0$"], answer: 0, solution: "1. Kalikan sekawan: $\\frac{\\sqrt{x}-2}{x-4} \\cdot \\frac{\\sqrt{x}+2}{\\sqrt{x}+2} = \\frac{1}{\\sqrt{x}+2}$. 2. Substitusi $x = 4$: $\\frac{1}{2+2} = \\frac{1}{4}$. 3. Jadi limitnya $\\frac{1}{4}$." },
    { q: "Nilai $\\lim_{x \\to 0} \\frac{x^2+5x}{3x}$ adalah ...", options: ["$0$", "$\\frac{5}{3}$", "$5$", "$\\frac{3}{5}$"], answer: 1, solution: "1. Faktorkan: $\\frac{x(x+5)}{3x} = \\frac{x+5}{3}$. 2. Substitusi $x = 0$: $\\frac{5}{3}$. 3. Jadi limitnya $\\frac{5}{3}$." },
    { q: "Nilai $\\lim_{x \\to 5} \\frac{x^2-25}{x^2-3x-10}$ adalah ...", options: ["$\\frac{5}{2}$", "$1$", "$\\frac{10}{7}$", "$2$"], answer: 2, solution: "1. Faktorkan: $\\frac{(x-5)(x+5)}{(x-5)(x+2)} = \\frac{x+5}{x+2}$. 2. Substitusi $x = 5$: $\\frac{10}{7}$. 3. Jadi limitnya $\\frac{10}{7}$." },
    { q: "Nilai $\\lim_{x \\to -1} \\frac{2x^2+3x+1}{x+1}$ adalah ...", options: ["$1$", "$0$", "$-3$", "$-1$"], answer: 3, solution: "1. Faktorkan: $\\frac{(2x+1)(x+1)}{x+1} = 2x+1$. 2. Substitusi $x = -1$: $2(-1)+1 = -1$. 3. Jadi limitnya $-1$." },
    { q: "Nilai $\\lim_{x \\to 2} \\frac{x^3-8}{x-2}$ adalah ...", options: ["$12$", "$4$", "$8$", "$6$"], answer: 0, solution: "1. Faktorkan: $\\frac{(x-2)(x^2+2x+4)}{x-2} = x^2+2x+4$. 2. Substitusi $x = 2$: $4+4+4 = 12$. 3. Jadi limitnya $12$." },
    { q: "Nilai $\\lim_{x \\to 0} \\frac{\\sin 5x}{2x}$ adalah ...", options: ["$5$", "$\\frac{2}{5}$", "$\\frac{5}{2}$", "$1$"], answer: 2, solution: "1. Tulis $\\frac{\\sin 5x}{2x} = \\frac{5}{2} \\cdot \\frac{\\sin 5x}{5x}$. 2. Karena $\\lim_{x \\to 0} \\frac{\\sin 5x}{5x} = 1$, hasilnya $\\frac{5}{2} \\cdot 1 = \\frac{5}{2}$. 3. Jadi limitnya $\\frac{5}{2}$." },
    { q: "Nilai $\\lim_{x \\to 0} \\frac{\\tan 3x}{\\sin 2x}$ adalah ...", options: ["$3$", "$\\frac{2}{3}$", "$1$", "$\\frac{3}{2}$"], answer: 3, solution: "1. Tulis $\\frac{\\tan 3x}{\\sin 2x} = \\frac{3}{2} \\cdot \\frac{\\tan 3x}{3x} \\cdot \\frac{2x}{\\sin 2x}$. 2. Kedua limit pecahannya $= 1$, hasilnya $\\frac{3}{2}$. 3. Jadi limitnya $\\frac{3}{2}$." },
    { q: "Nilai $\\lim_{x \\to 0} \\frac{1-\\cos 2x}{x^2}$ adalah ...", options: ["$2$", "$1$", "$4$", "$0$"], answer: 0, solution: "1. Gunakan $1-\\cos 2x = 2\\sin^2 x$. 2. $\\frac{2\\sin^2 x}{x^2} = 2\\left(\\frac{\\sin x}{x}\\right)^2 \\to 2 \\cdot 1 = 2$. 3. Jadi limitnya $2$." },
    { q: "Nilai $\\lim_{x \\to 0} \\frac{\\sin^2 4x}{x \\tan 2x}$ adalah ...", options: ["$4$", "$8$", "$2$", "$16$"], answer: 1, solution: "1. Tulis $\\frac{\\sin^2 4x}{x \\tan 2x} = \\frac{\\sin 4x}{x} \\cdot \\frac{\\sin 4x}{\\tan 2x}$. 2. Limitnya $4 \\cdot \\frac{4}{2} = 8$. 3. Jadi limitnya $8$." },
    { q: "Nilai $\\lim_{x \\to \\infty} \\frac{3x^2-5x+1}{2x^2+7}$ adalah ...", options: ["$3$", "$0$", "$\\infty$", "$\\frac{3}{2}$"], answer: 3, solution: "1. Pangkat tertinggi sama, bagi pembilang dan penyebut dengan $x^2$. 2. Limitnya $= \\frac{3}{2}$. 3. Jadi jawabannya $\\frac{3}{2}$." },
    { q: "Nilai $\\lim_{x \\to \\infty} \\frac{4x^3+2x}{x^3-5}$ adalah ...", options: ["$4$", "$2$", "$0$", "$\\infty$"], answer: 0, solution: "1. Pangkat tertinggi sama, bagi pembilang dan penyebut dengan $x^3$. 2. Limitnya $= \\frac{4}{1} = 4$. 3. Jadi jawabannya $4$." },
    { q: "Nilai $\\lim_{x \\to \\infty} (\\sqrt{x^2+4x}-x)$ adalah ...", options: ["$4$", "$2$", "$0$", "$1$"], answer: 1, solution: "1. Kalikan sekawan: $\\frac{4x}{\\sqrt{x^2+4x}+x}$. 2. Bagi dengan $x$: $\\frac{4}{\\sqrt{1+\\frac{4}{x}}+1} \\to \\frac{4}{2} = 2$. 3. Jadi limitnya $2$." },
    { q: "Nilai $\\lim_{x \\to \\infty} (\\sqrt{4x^2+3x+1}-2x)$ adalah ...", options: ["$3$", "$0$", "$\\frac{3}{4}$", "$\\frac{1}{2}$"], answer: 2, solution: "1. Kalikan sekawan: $\\frac{3x+1}{\\sqrt{4x^2+3x+1}+2x}$. 2. Bagi dengan $x$: hasilnya $\\to \\frac{3}{2+2} = \\frac{3}{4}$. 3. Jadi limitnya $\\frac{3}{4}$." },
    { q: "Turunan pertama dari $f(x) = 4x^3-2x^2+7x-1$ adalah ...", options: ["$12x^2-4x+7$", "$12x^2-4x$", "$4x^2-2x+7$", "$12x^3-4x^2+7x$"], answer: 0, solution: "1. Turunkan tiap suku: $12x^2 - 4x + 7 - 0$. 2. Sederhanakan: $f'(x) = 12x^2-4x+7$. 3. Jadi jawabannya $12x^2-4x+7$." },
    { q: "Turunan pertama dari $f(x) = x^4+3x^3-6x$ adalah ...", options: ["$4x^3+3x^2-6$", "$4x^3+9x^2-6$", "$x^3+3x^2-6$", "$4x^3+9x^2$"], answer: 1, solution: "1. Turunkan tiap suku: $4x^3 + 9x^2 - 6$. 2. Konstanta hilang, pangkat turun satu. 3. Jadi $f'(x) = 4x^3+9x^2-6$." },
    { q: "Turunan pertama dari $f(x) = (3x+2)^5$ adalah ...", options: ["$5(3x+2)^4$", "$(3x+2)^4$", "$15(3x+2)^4$", "$5(3x+2)^5$"], answer: 2, solution: "1. Aturan rantai: $f'(x) = 5(3x+2)^4 \\cdot 3$. 2. Kalikan: $5 \\cdot 3 = 15$. 3. Jadi $f'(x) = 15(3x+2)^4$." },
    { q: "Turunan pertama dari $f(x) = x^2(2x-1)$ adalah ...", options: ["$2x(2x-1)$", "$4x^2-2x$", "$6x^2-1$", "$6x^2-2x$"], answer: 3, solution: "1. Aturan hasil kali: $f'(x) = 2x(2x-1) + x^2(2)$. 2. Sederhanakan: $4x^2-2x+2x^2 = 6x^2-2x$. 3. Jadi $f'(x) = 6x^2-2x$." },
    { q: "Turunan pertama dari $f(x) = \\frac{2x+1}{x-3}$ adalah ...", options: ["$\\frac{-7}{(x-3)^2}$", "$\\frac{7}{(x-3)^2}$", "$\\frac{2x-5}{(x-3)^2}$", "$\\frac{-7}{x-3}$"], answer: 0, solution: "1. Aturan hasil bagi: $f'(x) = \\frac{2(x-3)-(2x+1)}{(x-3)^2}$. 2. Pembilang: $2x-6-2x-1 = -7$. 3. Jadi $f'(x) = \\frac{-7}{(x-3)^2}$." },
    { q: "Turunan pertama dari $f(x) = \\sqrt{x} + \\frac{1}{x}$ adalah ...", options: ["$\\frac{1}{2\\sqrt{x}}+\\frac{1}{x^2}$", "$\\frac{1}{2\\sqrt{x}}-\\frac{1}{x^2}$", "$\\sqrt{x}-\\frac{1}{x}$", "$\\frac{1}{2}x^{-\\frac{1}{2}}$"], answer: 1, solution: "1. Tulis $f(x) = x^{\\frac{1}{2}} + x^{-1}$. 2. Turunkan: $f'(x) = \\frac{1}{2}x^{-\\frac{1}{2}} - x^{-2} = \\frac{1}{2\\sqrt{x}} - \\frac{1}{x^2}$. 3. Jadi jawabannya $\\frac{1}{2\\sqrt{x}}-\\frac{1}{x^2}$." },
    { q: "Turunan pertama dari $f(x) = (x^2+1)(x^3-2)$ adalah ...", options: ["$2x(x^3-2)$", "$5x^4-4x$", "$5x^4+3x^2-4x$", "$3x^2(x^2+1)$"], answer: 2, solution: "1. Aturan hasil kali: $f'(x) = 2x(x^3-2) + (x^2+1)(3x^2)$. 2. Jabarkan: $2x^4-4x+3x^4+3x^2 = 5x^4+3x^2-4x$. 3. Jadi $f'(x) = 5x^4+3x^2-4x$." },
    { q: "Turunan pertama dari $f(x) = \\sqrt{2x^2+3}$ adalah ...", options: ["$\\frac{1}{2\\sqrt{2x^2+3}}$", "$\\frac{4x}{\\sqrt{2x^2+3}}$", "$\\frac{x}{\\sqrt{2x^2+3}}$", "$\\frac{2x}{\\sqrt{2x^2+3}}$"], answer: 3, solution: "1. Aturan rantai: $f'(x) = \\frac{1}{2\\sqrt{2x^2+3}} \\cdot 4x$. 2. Sederhanakan: $\\frac{2x}{\\sqrt{2x^2+3}}$. 3. Jadi $f'(x) = \\frac{2x}{\\sqrt{2x^2+3}}$." },
    { q: "Gradien garis singgung kurva $y = x^2+3x$ di $x = 1$ adalah ...", options: ["$4$", "$5$", "$8$", "$3$"], answer: 1, solution: "1. $y' = 2x+3$. 2. Substitusi $x = 1$: $y'(1) = 2+3 = 5$. 3. Jadi gradiennya $5$." },
    { q: "Gradien garis singgung kurva $y = x^3-2x^2$ di $x = 2$ adalah ...", options: ["$8$", "$0$", "$4$", "$12$"], answer: 2, solution: "1. $y' = 3x^2-4x$. 2. Substitusi $x = 2$: $y'(2) = 12-8 = 4$. 3. Jadi gradiennya $4$." },
    { q: "Persamaan garis singgung kurva $y = x^2-4x+3$ di $x = 2$ adalah ...", options: ["$y=2x+1$", "$y=4x-9$", "$y=x-3$", "$y=-1$"], answer: 3, solution: "1. Titik singgung: $x = 2$, $y = 4-8+3 = -1$. 2. Gradien: $y' = 2x-4$, di $x = 2$ gradiennya $0$. 3. Persamaan garis: $y = -1$." },
    { q: "Persamaan garis singgung kurva $y = x^2$ di titik $(3,9)$ adalah ...", options: ["$y=6x-9$", "$y=6x+9$", "$y=3x$", "$y=2x+3$"], answer: 0, solution: "1. Gradien: $y' = 2x$, di $(3,9)$ gradiennya $6$. 2. Persamaan: $y-9 = 6(x-3)$. 3. Jadi $y = 6x-9$." },
    { q: "Nilai maksimum dari $f(x) = -x^2+6x-5$ adalah ...", options: ["$5$", "$9$", "$4$", "$3$"], answer: 2, solution: "1. $f'(x) = -2x+6 = 0$ memberi $x = 3$. 2. $f(3) = -9+18-5 = 4$. 3. Jadi nilai maksimumnya $4$." },
    { q: "Nilai minimum dari $f(x) = 2x^2-8x+3$ adalah ...", options: ["$3$", "$8$", "$2$", "$-5$"], answer: 3, solution: "1. $f'(x) = 4x-8 = 0$ memberi $x = 2$. 2. $f(2) = 8-16+3 = -5$. 3. Jadi nilai minimumnya $-5$." },
    { q: "Sebuah persegi panjang memiliki keliling $40$ cm. Luas maksimumnya adalah ...", options: ["$100$", "$200$", "$400$", "$80$"], answer: 0, solution: "1. Misal panjang $x$, lebar $20-x$, luas $L = 20x-x^2$. 2. $L' = 20-2x = 0$ memberi $x = 10$, luas $= 10 \\times 10 = 100$. 3. Jadi luas maksimumnya $100$ cm$^2$." },
    { q: "Titik-titik stasioner dari $f(x) = x^3-3x^2$ adalah ...", options: ["$(0,0)$ saja", "$(0,0)$ dan $(2,-4)$", "$(2,-4)$ saja", "$(0,2)$ dan $(2,0)$"], answer: 1, solution: "1. $f'(x) = 3x^2-6x = 3x(x-2) = 0$ memberi $x = 0$ atau $x = 2$. 2. $f(0) = 0$ dan $f(2) = 8-12 = -4$. 3. Jadi titik stasionernya $(0,0)$ dan $(2,-4)$." },
    { q: "Sebuah balon berbentuk bola dipompa sehingga volumenya bertambah $100$ cm$^3$/s. Laju pertambahan jari-jari saat $r = 5$ cm adalah ...", options: ["$\\frac{100}{\\pi}$", "$4\\pi$", "$\\frac{1}{\\pi}$", "$\\frac{1}{25\\pi}$"], answer: 2, solution: "1. $V = \\frac{4}{3}\\pi r^3$, maka $\\frac{dV}{dt} = 4\\pi r^2 \\frac{dr}{dt}$. 2. $100 = 4\\pi(25)\\frac{dr}{dt}$, sehingga $\\frac{dr}{dt} = \\frac{1}{\\pi}$. 3. Jadi lajunya $\\frac{1}{\\pi}$ cm/s." },
    { q: "Sebuah batu dilempar ke atas dengan $h(t) = 30t-5t^2$ meter. Tinggi maksimum yang dicapai batu adalah ...", options: ["$90$", "$30$", "$60$", "$45$"], answer: 3, solution: "1. $h'(t) = 30-10t = 0$ memberi $t = 3$. 2. $h(3) = 90-45 = 45$. 3. Jadi tinggi maksimumnya $45$ m." },
    { q: "Hasil dari $\\int (6x^2-4x+1) \\, dx$ adalah ...", options: ["$6x^3-4x^2+x+C$", "$2x^3-2x^2+C$", "$12x-4+C$", "$2x^3-2x^2+x+C$"], answer: 3, solution: "1. $\\int 6x^2 dx = 2x^3$, $\\int -4x dx = -2x^2$, $\\int 1 dx = x$. 2. Jumlahkan dan tambah $C$. 3. Jadi hasilnya $2x^3-2x^2+x+C$." },
    { q: "Hasil dari $\\int (2x^3-5) \\, dx$ adalah ...", options: ["$\\frac{1}{2}x^4-5x+C$", "$2x^4-5x+C$", "$\\frac{1}{2}x^4-5+C$", "$8x^2-5+C$"], answer: 0, solution: "1. $\\int 2x^3 dx = \\frac{2x^4}{4} = \\frac{1}{2}x^4$. 2. $\\int -5 dx = -5x$, tambah $C$. 3. Jadi hasilnya $\\frac{1}{2}x^4-5x+C$." },
    { q: "Hasil dari $\\int (x+1)^2 \\, dx$ adalah ...", options: ["$x^3+2x^2+x+C$", "$\\frac{x^3}{3}+x^2+x+C$", "$x^2+2x+1+C$", "$\\frac{x^3}{3}+x+C$"], answer: 1, solution: "1. Jabarkan: $(x+1)^2 = x^2+2x+1$. 2. Integralkan: $\\frac{x^3}{3}+x^2+x+C$. 3. Jadi hasilnya $\\frac{x^3}{3}+x^2+x+C$." },
    { q: "Hasil dari $\\int \\left(\\frac{4}{x}+3x\\right) \\, dx$ adalah ...", options: ["$4\\ln|x|+3x^2+C$", "$\\frac{4}{x^2}+3+C$", "$4\\ln|x|+\\frac{3}{2}x^2+C$", "$\\ln|x|+3x^2+C$"], answer: 2, solution: "1. $\\int \\frac{4}{x} dx = 4\\ln|x|$. 2. $\\int 3x dx = \\frac{3}{2}x^2$, tambah $C$. 3. Jadi hasilnya $4\\ln|x|+\\frac{3}{2}x^2+C$." },
    { q: "Hasil dari $\\int (2x-3)^4 \\, dx$ adalah ...", options: ["$\\frac{(2x-3)^5}{5}+C$", "$(2x-3)^5+C$", "$8(2x-3)^3+C$", "$\\frac{(2x-3)^5}{10}+C$"], answer: 3, solution: "1. Misal $u = 2x-3$, maka $dx = \\frac{du}{2}$. 2. $\\int u^4 \\frac{du}{2} = \\frac{u^5}{10} = \\frac{(2x-3)^5}{10}$. 3. Jadi hasilnya $\\frac{(2x-3)^5}{10}+C$." },
    { q: "Hasil dari $\\int \\sqrt{3x+1} \\, dx$ adalah ...", options: ["$\\frac{2}{9}(3x+1)^{\\frac{3}{2}}+C$", "$\\frac{2}{3}(3x+1)^{\\frac{3}{2}}+C$", "$\\frac{1}{3}\\sqrt{3x+1}+C$", "$2(3x+1)^{\\frac{3}{2}}+C$"], answer: 0, solution: "1. Tulis $\\int (3x+1)^{\\frac{1}{2}} dx$. 2. Hasilnya $\\frac{(3x+1)^{\\frac{3}{2}}}{\\frac{3}{2} \\cdot 3} = \\frac{2}{9}(3x+1)^{\\frac{3}{2}}+C$. 3. Jadi jawabannya $\\frac{2}{9}(3x+1)^{\\frac{3}{2}}+C$." },
    { q: "Hasil dari $\\int_0^1 (2x+3) \\, dx$ adalah ...", options: ["$4$", "$3$", "$5$", "$2$"], answer: 0, solution: "1. Antiturunan: $x^2+3x$. 2. Evaluasi: $(1+3)-(0) = 4$. 3. Jadi hasilnya $4$." },
    { q: "Hasil dari $\\int_1^2 (4x-1) \\, dx$ adalah ...", options: ["$6$", "$5$", "$4$", "$7$"], answer: 1, solution: "1. Antiturunan: $2x^2-x$. 2. Evaluasi: $(8-2)-(2-1) = 6-1 = 5$. 3. Jadi hasilnya $5$." },
    { q: "Hasil dari $\\int_0^3 x^2 \\, dx$ adalah ...", options: ["$6$", "$27$", "$9$", "$3$"], answer: 2, solution: "1. Antiturunan: $\\frac{x^3}{3}$. 2. Evaluasi: $\\frac{27}{3}-0 = 9$. 3. Jadi hasilnya $9$." },
    { q: "Hasil dari $\\int_{-1}^1 3x^2 \\, dx$ adalah ...", options: ["$0$", "$1$", "$-2$", "$2$"], answer: 3, solution: "1. Antiturunan: $x^3$. 2. Evaluasi: $1-(-1) = 2$. 3. Jadi hasilnya $2$." },
    { q: "Hasil dari $\\int_0^2 (x+2)^2 \\, dx$ adalah ...", options: ["$\\frac{56}{3}$", "$\\frac{8}{3}$", "$16$", "$\\frac{32}{3}$"], answer: 0, solution: "1. Jabarkan: $x^2+4x+4$, antiturunan $\\frac{x^3}{3}+2x^2+4x$. 2. Evaluasi di $2$: $\\frac{8}{3}+8+8 = \\frac{56}{3}$. 3. Jadi hasilnya $\\frac{56}{3}$." },
    { q: "Hasil dari $\\int_1^3 \\frac{6}{x^2} \\, dx$ adalah ...", options: ["$6$", "$4$", "$2$", "$-4$"], answer: 1, solution: "1. Tulis $6x^{-2}$, antiturunan $-\\frac{6}{x}$. 2. Evaluasi: $-2-(-6) = 4$. 3. Jadi hasilnya $4$." },
    { q: "Luas daerah yang dibatasi kurva $y = x^2$, sumbu-$x$, $x = 0$, dan $x = 2$ adalah ...", options: ["$4$", "$\\frac{4}{3}$", "$\\frac{8}{3}$", "$8$"], answer: 2, solution: "1. Luas $= \\int_0^2 x^2 dx$. 2. $= \\left[\\frac{x^3}{3}\\right]_0^2 = \\frac{8}{3}$. 3. Jadi luasnya $\\frac{8}{3}$ satuan luas." },
    { q: "Luas daerah yang dibatasi kurva $y = 4x$ dan $y = x^2$ adalah ...", options: ["$\\frac{16}{3}$", "$32$", "$\\frac{64}{3}$", "$\\frac{32}{3}$"], answer: 3, solution: "1. Titik potong: $x^2 = 4x$ memberi $x = 0$ dan $x = 4$. 2. Luas $= \\int_0^4 (4x-x^2) dx = \\left[2x^2-\\frac{x^3}{3}\\right]_0^4 = 32-\\frac{64}{3} = \\frac{32}{3}$. 3. Jadi luasnya $\\frac{32}{3}$ satuan luas." },
    { q: "Volume benda putar dari daerah $y = x^2$, $0 \\le x \\le 1$, diputar mengelilingi sumbu-$x$ adalah ...", options: ["$\\frac{\\pi}{5}$", "$\\pi$", "$\\frac{\\pi}{3}$", "$\\frac{2\\pi}{5}$"], answer: 0, solution: "1. Volume $= \\pi \\int_0^1 (x^2)^2 dx = \\pi \\int_0^1 x^4 dx$. 2. $= \\pi\\left[\\frac{x^5}{5}\\right]_0^1 = \\frac{\\pi}{5}$. 3. Jadi volumenya $\\frac{\\pi}{5}$ satuan volume." },
    { q: "Volume benda putar dari daerah $y = \\sqrt{x}$, $0 \\le x \\le 4$, diputar mengelilingi sumbu-$x$ adalah ...", options: ["$4\\pi$", "$8\\pi$", "$16\\pi$", "$\\frac{32\\pi}{3}$"], answer: 1, solution: "1. Volume $= \\pi \\int_0^4 (\\sqrt{x})^2 dx = \\pi \\int_0^4 x dx$. 2. $= \\pi\\left[\\frac{x^2}{2}\\right]_0^4 = 8\\pi$. 3. Jadi volumenya $8\\pi$ satuan volume." },
    { q: "Diketahui $\\vec{a} = (2,5)$ dan $\\vec{b} = (-1,3)$. Hasil $\\vec{a} + \\vec{b}$ adalah ...", options: ["$(1,8)$", "$(3,2)$", "$(-1,8)$", "$(1,-2)$"], answer: 0, solution: "1. Jumlahkan komponen $x$: $2+(-1) = 1$. 2. Jumlahkan komponen $y$: $5+3 = 8$. 3. Jadi $\\vec{a}+\\vec{b} = (1,8)$." },
    { q: "Diketahui $\\vec{a} = (4,-2)$. Hasil $3\\vec{a}$ adalah ...", options: ["$(7,1)$", "$(12,-6)$", "$(12,6)$", "$(4,-6)$"], answer: 1, solution: "1. Kalikan tiap komponen dengan $3$. 2. $3(4,-2) = (12,-6)$. 3. Jadi $3\\vec{a} = (12,-6)$." },
    { q: "Panjang vektor $\\vec{b} = (5,12)$ adalah ...", options: ["$17$", "$7$", "$13$", "$12$"], answer: 2, solution: "1. $|\\vec{b}| = \\sqrt{5^2+12^2}$. 2. $= \\sqrt{25+144} = \\sqrt{169} = 13$. 3. Jadi panjangnya $13$." },
    { q: "Diketahui $\\vec{a} = (1,-3)$ dan $\\vec{b} = (4,2)$. Hasil $\\vec{a} - \\vec{b}$ adalah ...", options: ["$(3,5)$", "$(-3,-1)$", "$(5,-1)$", "$(-3,-5)$"], answer: 3, solution: "1. Kurangkan komponen $x$: $1-4 = -3$. 2. Kurangkan komponen $y$: $-3-2 = -5$. 3. Jadi $\\vec{a}-\\vec{b} = (-3,-5)$." },
    { q: "Diketahui $\\vec{a} = (2,3)$ dan $\\vec{b} = (4,-1)$. Hasil $\\vec{a} \\cdot \\vec{b}$ adalah ...", options: ["$5$", "$11$", "$-5$", "$8$"], answer: 0, solution: "1. $\\vec{a} \\cdot \\vec{b} = (2)(4) + (3)(-1)$. 2. $= 8-3 = 5$. 3. Jadi hasil dot productnya $5$." },
    { q: "Panjang vektor $\\vec{a} = (6,-8)$ adalah ...", options: ["$14$", "$10$", "$2$", "$7$"], answer: 1, solution: "1. $|\\vec{a}| = \\sqrt{6^2+(-8)^2}$. 2. $= \\sqrt{36+64} = \\sqrt{100} = 10$. 3. Jadi panjangnya $10$." },
    { q: "Vektor satuan searah $\\vec{a} = (6,8)$ adalah ...", options: ["$(\\frac{6}{13},\\frac{8}{13})$", "$(1,1)$", "$(\\frac{3}{5},\\frac{4}{5})$", "$(\\frac{1}{6},\\frac{1}{8})$"], answer: 2, solution: "1. $|\\vec{a}| = \\sqrt{36+64} = 10$. 2. Vektor satuan $= \\frac{1}{10}(6,8) = (\\frac{3}{5},\\frac{4}{5})$. 3. Jadi vektor satuannya $(\\frac{3}{5},\\frac{4}{5})$." },
    { q: "Besar sudut antara $\\vec{a} = (1,0)$ dan $\\vec{b} = (1,1)$ adalah ...", options: ["$90^\\circ$", "$30^\\circ$", "$60^\\circ$", "$45^\\circ$"], answer: 3, solution: "1. $\\cos \\theta = \\frac{(1)(1)+(0)(1)}{1 \\cdot \\sqrt{2}} = \\frac{1}{\\sqrt{2}}$. 2. $\\cos \\theta = \\frac{\\sqrt{2}}{2}$ memberi $\\theta = 45^\\circ$. 3. Jadi sudutnya $45^\\circ$." },
    { q: "Besar sudut antara $\\vec{a} = (2,2)$ dan $\\vec{b} = (2,-2)$ adalah ...", options: ["$90^\\circ$", "$45^\\circ$", "$0^\\circ$", "$180^\\circ$"], answer: 0, solution: "1. $\\vec{a} \\cdot \\vec{b} = (2)(2)+(2)(-2) = 0$. 2. Dot product nol berarti kedua vektor tegak lurus. 3. Jadi sudutnya $90^\\circ$." },
    { q: "Panjang proyeksi vektor $\\vec{a} = (4,3)$ pada $\\vec{b} = (1,0)$ adalah ...", options: ["$5$", "$4$", "$3$", "$7$"], answer: 1, solution: "1. Panjang proyeksi $= \\frac{\\vec{a} \\cdot \\vec{b}}{|\\vec{b}|}$. 2. $= \\frac{4(1)+3(0)}{1} = 4$. 3. Jadi panjang proyeksinya $4$." },
    { q: "Proyeksi vektor $\\vec{a} = (2,1)$ pada $\\vec{b} = (1,1)$ adalah ...", options: ["$(2,1)$", "$(\\frac{3}{\\sqrt{2}},\\frac{3}{\\sqrt{2}})$", "$(\\frac{3}{2},\\frac{3}{2})$", "$(3,3)$"], answer: 2, solution: "1. Proyeksi $= \\frac{\\vec{a} \\cdot \\vec{b}}{|\\vec{b}|^2}\\vec{b} = \\frac{3}{2}(1,1)$. 2. $= (\\frac{3}{2},\\frac{3}{2})$. 3. Jadi vektor proyeksinya $(\\frac{3}{2},\\frac{3}{2})$." },
    { q: "Diketahui $\\vec{a} = (5,1)$ dan $\\vec{b} = (-2,3)$. Hasil $2\\vec{a}-3\\vec{b}$ adalah ...", options: ["$(4,-7)$", "$(16,11)$", "$(4,11)$", "$(16,-7)$"], answer: 3, solution: "1. $2\\vec{a} = (10,2)$ dan $3\\vec{b} = (-6,9)$. 2. $2\\vec{a}-3\\vec{b} = (10-(-6), 2-9) = (16,-7)$. 3. Jadi hasilnya $(16,-7)$." },
    { q: "Diketahui $\\vec{a} = (7,2)$ dan $\\vec{b} = (4,6)$. Panjang $|\\vec{a}-\\vec{b}|$ adalah ...", options: ["$5$", "$3$", "$7$", "$25$"], answer: 0, solution: "1. $\\vec{a}-\\vec{b} = (3,-4)$. 2. $|\\vec{a}-\\vec{b}| = \\sqrt{9+16} = 5$. 3. Jadi panjangnya $5$." },
    { q: "Besar sudut antara $\\vec{a} = (1,\\sqrt{3})$ dan $\\vec{b} = (\\sqrt{3},1)$ adalah ...", options: ["$60^\\circ$", "$30^\\circ$", "$45^\\circ$", "$90^\\circ$"], answer: 1, solution: "1. $\\vec{a} \\cdot \\vec{b} = \\sqrt{3}+\\sqrt{3} = 2\\sqrt{3}$, $|\\vec{a}| = |\\vec{b}| = 2$. 2. $\\cos \\theta = \\frac{2\\sqrt{3}}{4} = \\frac{\\sqrt{3}}{2}$, jadi $\\theta = 30^\\circ$. 3. Jadi sudutnya $30^\\circ$." },
    { q: "Diketahui $\\vec{a} = (2,-1)$ dan $\\vec{a}+\\vec{b} = (5,3)$. Vektor $\\vec{b}$ adalah ...", options: ["$(7,2)$", "$(-3,-4)$", "$(3,4)$", "$(3,-4)$"], answer: 2, solution: "1. $\\vec{b} = (\\vec{a}+\\vec{b}) - \\vec{a}$. 2. $= (5-2, 3-(-1)) = (3,4)$. 3. Jadi $\\vec{b} = (3,4)$." },

    { q: "Nilai dari $\\sin 120^\\circ - \\cos 240^\\circ$ adalah ...", options: ["$\\frac{\\sqrt{3}-1}{2}$", "$1$", "$\\frac{\\sqrt{3}+1}{2}$", "$\\frac{1-\\sqrt{3}}{2}$"], answer: 2, solution: "1. $\\sin 120^\\circ = \\sin(180^\\circ-60^\\circ) = \\sin 60^\\circ = \\frac{\\sqrt{3}}{2}$. 2. $\\cos 240^\\circ = \\cos(180^\\circ+60^\\circ) = -\\cos 60^\\circ = -\\frac{1}{2}$. 3. Hasil $= \\frac{\\sqrt{3}}{2} - (-\\frac{1}{2}) = \\frac{\\sqrt{3}+1}{2}$." },
    { q: "Nilai dari $\\tan 135^\\circ \\times \\sin 225^\\circ$ adalah ...", options: ["$-\\frac{\\sqrt{2}}{2}$", "$-1$", "$1$", "$\\frac{\\sqrt{2}}{2}$"], answer: 3, solution: "1. $\\tan 135^\\circ = \\tan(180^\\circ-45^\\circ) = -\\tan 45^\\circ = -1$. 2. $\\sin 225^\\circ = \\sin(180^\\circ+45^\\circ) = -\\sin 45^\\circ = -\\frac{\\sqrt{2}}{2}$. 3. Hasil $= (-1) \\times (-\\frac{\\sqrt{2}}{2}) = \\frac{\\sqrt{2}}{2}$." },
    { q: "Nilai dari $\\cos 300^\\circ - \\sin 210^\\circ$ adalah ...", options: ["$1$", "$0$", "$\\frac{1}{2}$", "$-1$"], answer: 0, solution: "1. $\\cos 300^\\circ = \\cos(360^\\circ-60^\\circ) = \\cos 60^\\circ = \\frac{1}{2}$. 2. $\\sin 210^\\circ = \\sin(180^\\circ+30^\\circ) = -\\sin 30^\\circ = -\\frac{1}{2}$. 3. Hasil $= \\frac{1}{2} - (-\\frac{1}{2}) = 1$." },
    { q: "Nilai dari $\\frac{\\sin 60^\\circ \\times \\tan 60^\\circ}{\\cos 30^\\circ}$ adalah ...", options: ["$\\frac{\\sqrt{3}}{2}$", "$\\sqrt{3}$", "$1$", "$3$"], answer: 1, solution: "1. $\\sin 60^\\circ = \\frac{\\sqrt{3}}{2}$, $\\tan 60^\\circ = \\sqrt{3}$, $\\cos 30^\\circ = \\frac{\\sqrt{3}}{2}$. 2. Pembilang $= \\frac{\\sqrt{3}}{2} \\times \\sqrt{3} = \\frac{3}{2}$. 3. Hasil $= \\frac{3/2}{\\sqrt{3}/2} = \\frac{3}{\\sqrt{3}} = \\sqrt{3}$." },
    { q: "Nilai dari $\\cot 150^\\circ$ adalah ...", options: ["$\\sqrt{3}$", "$\\frac{1}{\\sqrt{3}}$", "$-\\sqrt{3}$", "$-\\frac{1}{\\sqrt{3}}$"], answer: 2, solution: "1. $\\cot 150^\\circ = \\frac{\\cos 150^\\circ}{\\sin 150^\\circ}$. 2. $\\cos 150^\\circ = -\\frac{\\sqrt{3}}{2}$ dan $\\sin 150^\\circ = \\frac{1}{2}$. 3. Hasil $= \\frac{-\\sqrt{3}/2}{1/2} = -\\sqrt{3}$." },
    { q: "Diketahui $\\tan \\theta = -1$ dengan $\\theta$ di kuadran II. Nilai $\\cos \\theta$ adalah ...", options: ["$\\frac{\\sqrt{2}}{2}$", "$\\frac{1}{2}$", "$-\\frac{1}{2}$", "$-\\frac{\\sqrt{2}}{2}$"], answer: 3, solution: "1. $\\tan \\theta = -1$ di kuadran II berarti $\\theta = 135^\\circ$. 2. Di kuadran II nilai cosinus negatif. 3. $\\cos 135^\\circ = -\\cos 45^\\circ = -\\frac{\\sqrt{2}}{2}$." },
    { q: "Diketahui $\\sin x = \\frac{5}{13}$ dengan $x$ sudut lancip. Nilai $\\tan x$ adalah ...", options: ["$\\frac{5}{12}$", "$\\frac{5}{13}$", "$\\frac{12}{13}$", "$\\frac{12}{5}$"], answer: 0, solution: "1. $\\cos x = \\sqrt{1-\\sin^2 x} = \\sqrt{1-\\frac{25}{169}} = \\sqrt{\\frac{144}{169}} = \\frac{12}{13}$ (positif karena lancip). 2. $\\tan x = \\frac{\\sin x}{\\cos x}$. 3. $\\tan x = \\frac{5/13}{12/13} = \\frac{5}{12}$." },
    { q: "Bentuk sederhana dari $\\frac{\\sin^2 x + \\cos^2 x}{\\cos x}$ adalah ...", options: ["$\\sin x$", "$\\sec x$", "$\\cos x$", "$\\tan x$"], answer: 1, solution: "1. Identitas: $\\sin^2 x + \\cos^2 x = 1$. 2. Bentuk menjadi $\\frac{1}{\\cos x}$. 3. $\\frac{1}{\\cos x} = \\sec x$." },
    { q: "Nilai dari $\\sin x \\cdot \\cot x$ adalah ...", options: ["$\\sin x$", "$\\tan x$", "$\\cos x$", "$1$"], answer: 2, solution: "1. $\\cot x = \\frac{\\cos x}{\\sin x}$. 2. $\\sin x \\cdot \\frac{\\cos x}{\\sin x}$. 3. $\\sin x$ saling menghilangkan, tersisa $\\cos x$." },
    { q: "Himpunan penyelesaian dari $2 \\sin x = \\sqrt{3}$ untuk $0^\\circ \\le x < 360^\\circ$ adalah ...", options: ["$\\{30^\\circ, 150^\\circ\\}$", "$\\{45^\\circ, 135^\\circ\\}$", "$\\{60^\\circ, 300^\\circ\\}$", "$\\{60^\\circ, 120^\\circ\\}$"], answer: 3, solution: "1. $\\sin x = \\frac{\\sqrt{3}}{2}$. 2. Sudut di kuadran I: $x = 60^\\circ$. 3. Sudut di kuadran II: $x = 180^\\circ - 60^\\circ = 120^\\circ$." },
    { q: "Himpunan penyelesaian dari $2 \\cos^2 x - 1 = 0$ untuk $0^\\circ \\le x \\le 180^\\circ$ adalah ...", options: ["$\\{45^\\circ, 135^\\circ\\}$", "$\\{60^\\circ, 120^\\circ\\}$", "$\\{30^\\circ, 150^\\circ\\}$", "$\\{45^\\circ, 315^\\circ\\}$"], answer: 0, solution: "1. $\\cos^2 x = \\frac{1}{2}$ sehingga $\\cos x = \\pm\\frac{\\sqrt{2}}{2}$. 2. $\\cos x = \\frac{\\sqrt{2}}{2} \\to x = 45^\\circ$. 3. $\\cos x = -\\frac{\\sqrt{2}}{2} \\to x = 135^\\circ$." },
    { q: "Segitiga ABC dengan $a = 6$ cm, $b = 8$ cm, dan sudut $C = 60^\\circ$. Luas segitiga ABC adalah ...", options: ["$6\\sqrt{3}$ cm$^2$", "$12\\sqrt{3}$ cm$^2$", "$24\\sqrt{3}$ cm$^2$", "$12$ cm$^2$"], answer: 1, solution: "1. $L = \\frac{1}{2}ab\\sin C$. 2. $L = \\frac{1}{2} \\times 6 \\times 8 \\times \\sin 60^\\circ = 24 \\times \\frac{\\sqrt{3}}{2}$. 3. $L = 12\\sqrt{3}$ cm$^2$." },
    { q: "Segitiga ABC dengan $a = 10$ cm, sudut $A = 30^\\circ$, dan sudut $B = 45^\\circ$. Panjang sisi $b$ adalah ...", options: ["$5\\sqrt{2}$ cm", "$10$ cm", "$10\\sqrt{2}$ cm", "$5\\sqrt{6}$ cm"], answer: 2, solution: "1. Aturan sinus: $\\frac{b}{\\sin B} = \\frac{a}{\\sin A}$. 2. $b = \\frac{10 \\times \\sin 45^\\circ}{\\sin 30^\\circ} = \\frac{10 \\times \\sqrt{2}/2}{1/2}$. 3. $b = 10\\sqrt{2}$ cm." },
    { q: "Segitiga ABC dengan $a = 5$ cm, $b = 6$ cm, dan sudut $C = 60^\\circ$. Panjang sisi $c$ adalah ...", options: ["$\\sqrt{61}$ cm", "$\\sqrt{91}$ cm", "$7$ cm", "$\\sqrt{31}$ cm"], answer: 3, solution: "1. Aturan cosinus: $c^2 = a^2 + b^2 - 2ab\\cos C$. 2. $c^2 = 25 + 36 - 2(5)(6)\\cos 60^\\circ = 61 - 60(\\frac{1}{2}) = 31$. 3. $c = \\sqrt{31}$ cm." },
    { q: "Segitiga dengan panjang sisi 7 cm, 8 cm, dan 9 cm. Luas segitiga tersebut adalah ...", options: ["$12\\sqrt{5}$ cm$^2$", "$6\\sqrt{5}$ cm$^2$", "$24\\sqrt{5}$ cm$^2$", "$36$ cm$^2$"], answer: 0, solution: "1. $s = \\frac{7+8+9}{2} = 12$. 2. $L = \\sqrt{s(s-a)(s-b)(s-c)} = \\sqrt{12 \\times 5 \\times 4 \\times 3} = \\sqrt{720}$. 3. $\\sqrt{720} = 12\\sqrt{5}$ cm$^2$." },
    { q: "Jajar genjang dengan sisi 10 cm dan 14 cm mengapit sudut $60^\\circ$. Luas jajar genjang tersebut adalah ...", options: ["$140\\sqrt{3}$ cm$^2$", "$70\\sqrt{3}$ cm$^2$", "$35\\sqrt{3}$ cm$^2$", "$70$ cm$^2$"], answer: 1, solution: "1. $L = a \\times b \\times \\sin \\theta$. 2. $L = 10 \\times 14 \\times \\sin 60^\\circ = 140 \\times \\frac{\\sqrt{3}}{2}$. 3. $L = 70\\sqrt{3}$ cm$^2$." },
    { q: "Nilai maksimum dari $y = 3 \\sin x - 4 \\cos x$ adalah ...", options: ["$7$", "$1$", "$5$", "$12$"], answer: 2, solution: "1. Bentuk $a\\sin x + b\\cos x$ dapat ditulis $k\\cos(x-\\alpha)$ dengan $k = \\sqrt{a^2+b^2}$. 2. $k = \\sqrt{3^2+(-4)^2} = \\sqrt{25} = 5$. 3. Nilai maksimum $= k = 5$." },
    { q: "Nilai minimum dari $y = 2 + 3 \\cos x$ adalah ...", options: ["$2$", "$-3$", "$5$", "$-1$"], answer: 3, solution: "1. Nilai minimum $\\cos x = -1$. 2. Substitusi: $y = 2 + 3(-1)$. 3. $y = 2 - 3 = -1$." },
    { q: "Periode fungsi $y = 2 \\sin(3x + \\frac{\\pi}{4})$ adalah ...", options: ["$\\frac{2\\pi}{3}$", "$2\\pi$", "$\\pi$", "$\\frac{\\pi}{3}$"], answer: 0, solution: "1. Periode $y = A\\sin(Bx+C)$ adalah $\\frac{2\\pi}{|B|}$. 2. Di sini $B = 3$. 3. Periode $= \\frac{2\\pi}{3}$." },
    { q: "Amplitudo fungsi $y = -5 \\cos 2x$ adalah ...", options: ["$-5$", "$5$", "$2$", "$10$"], answer: 1, solution: "1. Amplitudo adalah nilai mutlak koefisien di depan cosinus. 2. Koefisien $= -5$. 3. Amplitudo $= |-5| = 5$." },
    { q: "Rata-rata dari data 5, 7, 9, 6, 8 adalah ...", options: ["$6$", "$8$", "$7$", "$6{,}5$"], answer: 2, solution: "1. Jumlah data $= 5+7+9+6+8 = 35$. 2. Banyak data $= 5$. 3. Rata-rata $= \\frac{35}{5} = 7$." },
    { q: "Median dari data 8, 3, 11, 5, 9 adalah ...", options: ["$5$", "$9$", "$11$", "$8$"], answer: 3, solution: "1. Urutkan data: 3, 5, 8, 9, 11. 2. Banyak data $n = 5$ (ganjil), median adalah data ke-$\\frac{5+1}{2} = $ data ke-3. 3. Data ke-3 $= 8$." },
    { q: "Modus dari data 2, 5, 3, 5, 7, 5, 8 adalah ...", options: ["$5$", "$7$", "$8$", "$2$"], answer: 0, solution: "1. Frekuensi tiap nilai: 2 muncul 1 kali, 5 muncul 3 kali, 3, 7, 8 masing-masing 1 kali. 2. Nilai dengan frekuensi terbanyak adalah 5. 3. Jadi modusnya $5$." },
    { q: "Rata-rata dari data 5, 6, 6, 7, 8, 10 adalah ...", options: ["$6$", "$7$", "$6{,}5$", "$7{,}5$"], answer: 1, solution: "1. Jumlah $= 5+6+6+7+8+10 = 42$. 2. Banyak data $= 6$. 3. Rata-rata $= \\frac{42}{6} = 7$." },
    { q: "Rata-rata 4 bilangan adalah 15. Jika ditambah sebuah bilangan 20, rata-rata yang baru adalah ...", options: ["$15$", "$17$", "$16$", "$18$"], answer: 2, solution: "1. Jumlah 4 bilangan $= 4 \\times 15 = 60$. 2. Setelah ditambah 20, jumlah $= 80$ dengan 5 bilangan. 3. Rata-rata baru $= \\frac{80}{5} = 16$." },
    { q: "Data berkelompok: 40-49 frekuensinya 4; 50-59 frekuensinya 6; 60-69 frekuensinya 8; 70-79 frekuensinya 2. Rata-ratanya adalah ...", options: ["$57{,}5$", "$59$", "$60$", "$58{,}5$"], answer: 3, solution: "1. Titik tengah tiap kelas: 44,5; 54,5; 64,5; 74,5. 2. $\\sum fx = 4(44{,}5)+6(54{,}5)+8(64{,}5)+2(74{,}5) = 178+327+516+149 = 1170$. 3. $\\bar{x} = \\frac{1170}{20} = 58{,}5$." },
    { q: "Data berkelompok: 50-59 (f = 4), 60-69 (f = 10), 70-79 (f = 6). Mediannya adalah ...", options: ["$65{,}5$", "$64{,}5$", "$65$", "$66$"], answer: 0, solution: "1. $n = 20$, letak median $= \\frac{20}{2} = 10$ sehingga kelas median 60-69. 2. $T_b = 59{,}5$, $f_k = 4$, $f = 10$, $p = 10$. 3. $Me = 59{,}5 + \\frac{10-4}{10} \\times 10 = 65{,}5$." },
    { q: "Data berkelompok: 60-69 (f = 8), 70-79 (f = 14), 80-89 (f = 8). Modusnya adalah ...", options: ["$74$", "$74{,}5$", "$75$", "$73{,}5$"], answer: 1, solution: "1. Kelas modus 70-79 dengan $T_b = 69{,}5$, $d_1 = 14-8 = 6$, $d_2 = 14-8 = 6$, $p = 10$. 2. $Mo = T_b + \\frac{d_1}{d_1+d_2} \\times p$. 3. $Mo = 69{,}5 + \\frac{6}{12} \\times 10 = 74{,}5$." },
    { q: "Data berkelompok: 40-49 (f = 4), 50-59 (f = 8), 60-69 (f = 6), 70-79 (f = 2). Kuartil bawahnya adalah ...", options: ["$50{,}25$", "$50{,}5$", "$50{,}75$", "$51$"], answer: 2, solution: "1. $n = 20$, letak $Q_1 = \\frac{20}{4} = 5$ sehingga kelas $Q_1$: 50-59. 2. $T_b = 49{,}5$, $f_k = 4$, $f = 8$, $p = 10$. 3. $Q_1 = 49{,}5 + \\frac{5-4}{8} \\times 10 = 50{,}75$." },
    { q: "Simpangan rata-rata dari data 4, 6, 8, 10, 12 adalah ...", options: ["$2$", "$2{,}2$", "$2{,}8$", "$2{,}4$"], answer: 3, solution: "1. Rata-rata $= \\frac{40}{5} = 8$. 2. Jumlah simpangan mutlak $= |4-8|+|6-8|+|8-8|+|10-8|+|12-8| = 4+2+0+2+4 = 12$. 3. $SR = \\frac{12}{5} = 2{,}4$." },
    { q: "Ragam (variansi) dari data 2, 4, 6, 8, 10 adalah ...", options: ["$8$", "$6$", "$10$", "$40$"], answer: 0, solution: "1. Rata-rata $= 6$. 2. Jumlah kuadrat simpangan $= 16+4+0+4+16 = 40$. 3. Ragam $= \\frac{40}{5} = 8$." },
    { q: "Penjualan buku lima hari: Senin 20, Selasa 35, Rabu 25, Kamis 40, Jumat 30. Total buku yang terjual adalah ...", options: ["$140$", "$150$", "$160$", "$170$"], answer: 1, solution: "1. Jumlahkan semua data harian. 2. $20+35+25+40+30 = 150$. 3. Jadi totalnya 150 buku." },
    { q: "Diagram lingkaran menunjukkan 25% dari 240 siswa gemar matematika. Banyak siswa yang gemar matematika adalah ...", options: ["$48$", "$72$", "$60$", "$80$"], answer: 2, solution: "1. Banyak siswa $= 25\\% \\times 240$. 2. $= \\frac{25}{100} \\times 240$. 3. $= 60$ siswa." },
    { q: "Data nilai ulangan: 60-69 ada 5 siswa, 70-79 ada 8 siswa, 80-89 ada 6 siswa, 90-100 ada 4 siswa. Banyak siswa yang nilainya minimal 70 adalah ...", options: ["$14$", "$16$", "$22$", "$18$"], answer: 3, solution: "1. Nilai minimal 70 mencakup kelas 70-79, 80-89, dan 90-100. 2. Jumlah $= 8+6+4$. 3. Hasil $= 18$ siswa." },
    { q: "Dari angka 1, 2, 3, 4, 5 akan disusun bilangan 3 angka yang berbeda. Banyak bilangan yang dapat disusun adalah ...", options: ["$60$", "$120$", "$15$", "$125$"], answer: 0, solution: "1. Ini permutasi karena urutan diperhatikan: $P(5,3)$. 2. $P(5,3) = 5 \\times 4 \\times 3$. 3. Hasil $= 60$." },
    { q: "Enam orang duduk mengelilingi meja bundar. Banyak susunan duduk yang mungkin adalah ...", options: ["$720$", "$120$", "$36$", "$60$"], answer: 1, solution: "1. Permutasi siklis $n$ objek $= (n-1)!$. 2. $(6-1)! = 5! = 120$. 3. Jadi ada 120 susunan." },
    { q: "Dari 10 siswa akan dipilih 3 orang untuk mengikuti lomba. Banyak cara memilih adalah ...", options: ["$720$", "$30$", "$120$", "$210$"], answer: 2, solution: "1. Ini kombinasi karena urutan tidak diperhatikan: $C(10,3)$. 2. $C(10,3) = \\frac{10 \\times 9 \\times 8}{3 \\times 2 \\times 1} = \\frac{720}{6}$. 3. Hasil $= 120$." },
    { q: "Banyak susunan huruf berbeda dari kata MATEMATIKA adalah ...", options: ["$362.880$", "$453.600$", "$907.200$", "$151.200$"], answer: 3, solution: "1. Ada 10 huruf dengan M muncul 2 kali, A 3 kali, T 2 kali. 2. $P = \\frac{10!}{2! \\times 3! \\times 2!} = \\frac{3.628.800}{24}$. 3. Hasil $= 151.200$." },
    { q: "Nomor undian terdiri dari 4 digit angka yang semuanya berbeda. Banyak nomor undian yang dapat dibuat adalah ...", options: ["$5.040$", "$10.000$", "$210$", "$720$"], answer: 0, solution: "1. Ini permutasi 4 dari 10 digit: $P(10,4)$. 2. $P(10,4) = 10 \\times 9 \\times 8 \\times 7$. 3. Hasil $= 5.040$." },
    { q: "Dari 8 calon akan dipilih ketua, sekretaris, dan bendahara. Banyak susunan pengurus yang mungkin adalah ...", options: ["$56$", "$336$", "$512$", "$24$"], answer: 1, solution: "1. Jabatan berbeda sehingga urutan diperhatikan: $P(8,3)$. 2. $P(8,3) = 8 \\times 7 \\times 6$. 3. Hasil $= 336$." },
    { q: "Huruf-huruf vokal pada kata PELUANG disusun menjadi susunan baru (boleh tidak bermakna). Banyak susunan yang mungkin adalah ...", options: ["$24$", "$3$", "$6$", "$12$"], answer: 2, solution: "1. Huruf vokal pada PELUANG: E, U, A (3 huruf berbeda). 2. Banyak susunan $= 3!$. 3. $3! = 6$." },
    { q: "Dari angka 1, 2, 3, 4, 5, 6 disusun bilangan genap 3 angka tanpa pengulangan. Banyak bilangan yang terbentuk adalah ...", options: ["$120$", "$36$", "$90$", "$60$"], answer: 3, solution: "1. Angka satuan harus genap: 2, 4, atau 6 (3 pilihan). 2. Dua angka depan dipilih dari 5 angka tersisa: $P(5,2) = 20$. 3. Total $= 3 \\times 20 = 60$." },
    { q: "Dari 5 pria dan 4 wanita dipilih 3 orang dengan syarat minimal 1 wanita. Banyak cara memilih adalah ...", options: ["$74$", "$84$", "$64$", "$94$"], answer: 0, solution: "1. Total cara tanpa syarat: $C(9,3) = 84$. 2. Cara tanpa wanita (semua pria): $C(5,3) = 10$. 3. Cara dengan minimal 1 wanita $= 84 - 10 = 74$." },
    { q: "Dalam sebuah pertemuan ada 12 orang dan setiap orang saling berjabat tangan tepat satu kali. Banyak jabat tangan yang terjadi adalah ...", options: ["$132$", "$66$", "$144$", "$24$"], answer: 1, solution: "1. Setiap jabat tangan melibatkan 2 orang tanpa memperhatikan urutan: $C(12,2)$. 2. $C(12,2) = \\frac{12 \\times 11}{2}$. 3. Hasil $= 66$." },
    { q: "Dua dadu dilempar bersamaan. Peluang muncul jumlah mata dadu 9 adalah ...", options: ["$\\frac{1}{6}$", "$\\frac{1}{12}$", "$\\frac{1}{9}$", "$\\frac{5}{36}$"], answer: 2, solution: "1. Pasangan berjumlah 9: (3,6), (4,5), (5,4), (6,3), ada 4 kejadian. 2. Ruang sampel $= 36$. 3. Peluang $= \\frac{4}{36} = \\frac{1}{9}$." },
    { q: "Sebuah koin dilempar 3 kali. Peluang muncul tepat 2 gambar adalah ...", options: ["$\\frac{1}{2}$", "$\\frac{1}{4}$", "$\\frac{1}{8}$", "$\\frac{3}{8}$"], answer: 3, solution: "1. Ruang sampel $= 2^3 = 8$. 2. Kejadian tepat 2 gambar: GGA, GAG, AGG, ada 3 kejadian. 3. Peluang $= \\frac{3}{8}$." },
    { q: "Satu kartu diambil dari setumpuk kartu bridge. Peluang terambil kartu hati atau kartu As adalah ...", options: ["$\\frac{4}{13}$", "$\\frac{17}{52}$", "$\\frac{1}{4}$", "$\\frac{5}{13}$"], answer: 0, solution: "1. $P(\\text{hati}) = \\frac{13}{52}$, $P(\\text{As}) = \\frac{4}{52}$, $P(\\text{As hati}) = \\frac{1}{52}$. 2. $P = \\frac{13}{52} + \\frac{4}{52} - \\frac{1}{52} = \\frac{16}{52}$. 3. $\\frac{16}{52} = \\frac{4}{13}$." },
    { q: "Dalam kotak ada 5 bola merah dan 3 bola biru. Diambil 2 bola sekaligus. Peluang keduanya berwarna merah adalah ...", options: ["$\\frac{5}{28}$", "$\\frac{5}{14}$", "$\\frac{1}{4}$", "$\\frac{2}{7}$"], answer: 1, solution: "1. Cara mengambil 2 merah: $C(5,2) = 10$. 2. Total cara mengambil 2 bola: $C(8,2) = 28$. 3. Peluang $= \\frac{10}{28} = \\frac{5}{14}$." },
    { q: "Sebuah dadu dilempar. Diketahui muncul mata dadu bilangan genap. Peluang muncul mata dadu 4 adalah ...", options: ["$\\frac{1}{6}$", "$\\frac{1}{2}$", "$\\frac{1}{3}$", "$\\frac{2}{3}$"], answer: 2, solution: "1. Ruang sampel baru (bilangan genap): $\\{2, 4, 6\\}$, ada 3. 2. Kejadian yang dimaksud: $\\{4\\}$, ada 1. 3. Peluang $= \\frac{1}{3}$." },
    { q: "Peluang sukses pada tiap percobaan adalah $\\frac{1}{2}$. Peluang tepat 3 kali sukses dari 5 percobaan adalah ...", options: ["$\\frac{1}{2}$", "$\\frac{3}{8}$", "$\\frac{1}{4}$", "$\\frac{5}{16}$"], answer: 3, solution: "1. Distribusi binomial: $C(5,3) \\times (\\frac{1}{2})^3 \\times (\\frac{1}{2})^2$. 2. $= 10 \\times \\frac{1}{32}$. 3. $= \\frac{10}{32} = \\frac{5}{16}$." },
    { q: "Dua dadu dilempar. Peluang mata dadu pertama 6 atau jumlah kedua mata dadu 7 adalah ...", options: ["$\\frac{11}{36}$", "$\\frac{12}{36}$", "$\\frac{1}{3}$", "$\\frac{7}{36}$"], answer: 0, solution: "1. $P(\\text{dadu pertama } 6) = \\frac{6}{36}$, $P(\\text{jumlah } 7) = \\frac{6}{36}$, irisannya yaitu (6,1) $= \\frac{1}{36}$. 2. $P = \\frac{6}{36} + \\frac{6}{36} - \\frac{1}{36}$. 3. $= \\frac{11}{36}$." },
    { q: "Kotak berisi 4 bola putih dan 6 bola hitam. Diambil satu per satu tanpa pengembalian sebanyak 2 kali. Peluang keduanya putih adalah ...", options: ["$\\frac{1}{6}$", "$\\frac{2}{15}$", "$\\frac{1}{5}$", "$\\frac{4}{25}$"], answer: 1, solution: "1. Pengambilan pertama: $\\frac{4}{10}$. 2. Pengambilan kedua (tersisa 3 putih dari 9 bola): $\\frac{3}{9}$. 3. Peluang $= \\frac{4}{10} \\times \\frac{3}{9} = \\frac{12}{90} = \\frac{2}{15}$." },
    { q: "Peluang tidak hujan hari ini adalah 0,7. Peluang hujan tiga hari berturut-turut adalah ...", options: ["$0{,}09$", "$0{,}3$", "$0{,}027$", "$0{,}7$"], answer: 2, solution: "1. Peluang hujan dalam sehari $= 1 - 0{,}7 = 0{,}3$. 2. Kejadian saling bebas: $0{,}3 \\times 0{,}3 \\times 0{,}3$. 3. Hasil $= 0{,}027$." },
    { q: "Peluang seorang siswa lulus ujian adalah 85%. Peluang ia gagal dalam dua ujian berturut-turut adalah ...", options: ["$\\frac{3}{40}$", "$\\frac{9}{200}$", "$\\frac{1}{40}$", "$\\frac{9}{400}$"], answer: 3, solution: "1. Peluang gagal sekali $= 1 - 0{,}85 = 0{,}15 = \\frac{3}{20}$. 2. Gagal dua kali berturut-turut: $\\frac{3}{20} \\times \\frac{3}{20} = \\frac{9}{400}$. 3. Hasil $= \\frac{9}{400}$." },
    { q: "Sebuah dadu dilempar 120 kali. Frekuensi harapan muncul mata dadu genap adalah ...", options: ["$60$", "$40$", "$80$", "$30$"], answer: 0, solution: "1. Peluang mata genap $= \\frac{3}{6} = \\frac{1}{2}$. 2. Frekuensi harapan $=$ peluang $\\times$ banyak percobaan. 3. $= \\frac{1}{2} \\times 120 = 60$." },
    { q: "Dua kartu diambil berurutan tanpa pengembalian dari kartu bridge. Peluang keduanya berwarna merah adalah ...", options: ["$\\frac{1}{4}$", "$\\frac{25}{102}$", "$\\frac{25}{51}$", "$\\frac{13}{51}$"], answer: 1, solution: "1. Kartu pertama merah: $\\frac{26}{52}$. 2. Kartu kedua merah (tersisa 25 dari 51): $\\frac{25}{51}$. 3. Peluang $= \\frac{26}{52} \\times \\frac{25}{51} = \\frac{25}{102}$." },
    { q: "Nilai maksimum $z = 3x + 5y$ dengan kendala $x + y \\le 12$, $2x + y \\le 16$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$52$", "$48$", "$60$", "$36$"], answer: 2, solution: "1. Titik-titik pojok: (0,0), (8,0), titik potong (4,8), (0,12). 2. $z(8,0) = 24$, $z(4,8) = 52$, $z(0,12) = 60$. 3. Nilai maksimum $= 60$." },
    { q: "Roti A butuh 2 kg tepung dan 1 kg gula, roti B butuh 1 kg tepung dan 2 kg gula. Tersedia 10 kg tepung dan 8 kg gula. Model matematika yang tepat adalah ...", options: ["$x + 2y \\le 10;\\ 2x + y \\le 8;\\ x \\ge 0;\\ y \\ge 0$", "$2x + y \\ge 10;\\ x + 2y \\ge 8;\\ x \\ge 0;\\ y \\ge 0$", "$2x + 2y \\le 18;\\ x \\ge 0;\\ y \\ge 0$", "$2x + y \\le 10;\\ x + 2y \\le 8;\\ x \\ge 0;\\ y \\ge 0$"], answer: 3, solution: "1. Misalkan roti A $= x$ dan roti B $= y$. 2. Kebutuhan tepung: $2x + y \\le 10$; kebutuhan gula: $x + 2y \\le 8$. 3. Ditambah syarat $x \\ge 0$, $y \\ge 0$." },
    { q: "Nilai minimum $z = 4x + 3y$ dengan kendala $x + y \\ge 6$, $2x + y \\ge 8$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$20$", "$24$", "$18$", "$16$"], answer: 0, solution: "1. Titik-titik pojok: (0,8), titik potong (2,4), (6,0). 2. $z(0,8) = 24$, $z(2,4) = 20$, $z(6,0) = 24$. 3. Nilai minimum $= 20$." },
    { q: "Titik berikut yang memenuhi sistem $x + 2y \\le 10$, $2x + y \\le 11$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$(4, 4)$", "$(3, 2)$", "$(2, 5)$", "$(5, 2)$"], answer: 1, solution: "1. Uji (3,2): $3+4 = 7 \\le 10$ dan $6+2 = 8 \\le 11$ (memenuhi). 2. (4,4): $4+8 = 12 > 10$ (tidak memenuhi). 3. (2,5): $2+10 = 12 > 10$ (tidak); (5,2): $10+2 = 12 > 11$ (tidak)." },
    { q: "Nilai maksimum $z = 5x + 4y$ dengan kendala $x + y \\le 10$, $x + 2y \\le 14$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$46$", "$48$", "$50$", "$56$"], answer: 2, solution: "1. Titik-titik pojok: (0,0), (10,0), titik potong (6,4), (0,7). 2. $z(10,0) = 50$, $z(6,4) = 46$, $z(0,7) = 28$. 3. Nilai maksimum $= 50$." },
    { q: "Meja (x) butuh 4 jam kerja dan 3 unit bahan; kursi (y) butuh 2 jam kerja dan 2 unit bahan. Tersedia 100 jam kerja dan 90 unit bahan. Model matematika yang tepat adalah ...", options: ["$2x + 4y \\le 100;\\ 2x + 3y \\le 90;\\ x \\ge 0;\\ y \\ge 0$", "$4x + 2y \\ge 100;\\ 3x + 2y \\ge 90;\\ x \\ge 0;\\ y \\ge 0$", "$4x + 3y \\le 100;\\ 2x + 2y \\le 90;\\ x \\ge 0;\\ y \\ge 0$", "$4x + 2y \\le 100;\\ 3x + 2y \\le 90;\\ x \\ge 0;\\ y \\ge 0$"], answer: 3, solution: "1. Batasan jam kerja: $4x + 2y \\le 100$. 2. Batasan bahan: $3x + 2y \\le 90$. 3. Ditambah syarat $x \\ge 0$, $y \\ge 0$." },
    { q: "Nilai maksimum $z = 3x + 2y$ dengan kendala $x + 3y \\le 18$, $2x + y \\le 16$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$26$", "$24$", "$28$", "$22$"], answer: 0, solution: "1. Titik-titik pojok: (0,0), (8,0), titik potong (6,4), (0,6). 2. $z(8,0) = 24$, $z(6,4) = 26$, $z(0,6) = 12$. 3. Nilai maksimum $= 26$." },
    { q: "Nilai minimum $z = x + 3y$ dengan kendala $x + y \\ge 5$, $2x + y \\ge 8$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$8$", "$5$", "$9$", "$24$"], answer: 1, solution: "1. Titik-titik pojok: (0,8), titik potong (3,2), (5,0). 2. $z(0,8) = 24$, $z(3,2) = 9$, $z(5,0) = 5$. 3. Nilai minimum $= 5$." },
    { q: "Toko menjual tas (x, laba Rp50.000) dan sepatu (y, laba Rp80.000). Kapasitas toko 60 barang; modal tiap tas Rp100.000 dan tiap sepatu Rp200.000 dengan total modal Rp8.000.000. Laba maksimum yang diperoleh adalah ...", options: ["Rp3.000.000", "Rp3.200.000", "Rp3.600.000", "Rp4.000.000"], answer: 2, solution: "1. Model (dalam ratusan ribu): $x+y \\le 60$, $x+2y \\le 80$, $z = 50x+80y$. 2. Titik pojok: (60,0) $\\to$ 3000, (40,20) $\\to$ 3600, (0,40) $\\to$ 3200. 3. Maksimum 3600 (ratusan ribu) $=$ Rp3.600.000." },
    { q: "Titik potong garis $x + y = 6$ dan $x + 2y = 8$ adalah ...", options: ["$(2, 4)$", "$(6, 2)$", "$(4, 4)$", "$(4, 2)$"], answer: 3, solution: "1. Kurangkan kedua persamaan: $(x+2y) - (x+y) = 8 - 6$. 2. Diperoleh $y = 2$. 3. Substitusi ke $x+y = 6$: $x = 4$." },
    { q: "Nilai maksimum $z = 4x + 3y$ dengan kendala $x + 2y \\le 10$, $2x + y \\le 11$, $x \\ge 0$, $y \\ge 0$ adalah ...", options: ["$25$", "$22$", "$27$", "$20$"], answer: 0, solution: "1. Titik-titik pojok: (0,0), (5{,}5, 0), titik potong (4,3), (0,5). 2. $z(5{,}5, 0) = 22$, $z(4,3) = 25$, $z(0,5) = 15$. 3. Nilai maksimum $= 25$." },
    { q: "Biaya produksi barang A Rp30.000 dan barang B Rp50.000 dengan kendala $x + y \\ge 100$ dan $2x + 3y \\ge 240$. Biaya produksi minimum adalah ...", options: ["Rp3.800.000", "Rp3.600.000", "Rp5.000.000", "Rp3.000.000"], answer: 1, solution: "1. Fungsi tujuan $z = 30x + 50y$ (dalam ribuan). Titik pojok: (0,100), (60,40), (120,0). 2. $z(0,100) = 5000$, $z(60,40) = 3800$, $z(120,0) = 3600$. 3. Minimum 3600 (ribuan) $=$ Rp3.600.000." },
    { q: "Titik berikut yang termuat dalam daerah penyelesaian $2x + 3y \\le 12$ adalah ...", options: ["$(4, 3)$", "$(5, 2)$", "$(1, 1)$", "$(3, 4)$"], answer: 2, solution: "1. Uji (1,1): $2+3 = 5 \\le 12$ (memenuhi). 2. (4,3): $8+9 = 17 > 12$; (5,2): $10+6 = 16 > 12$ (tidak memenuhi). 3. (3,4): $6+12 = 18 > 12$ (tidak memenuhi)." },
    { q: "Kubus ABCD.EFGH dengan rusuk 6 cm. Jarak titik A ke titik C adalah ...", options: ["$6$ cm", "$6\\sqrt{3}$ cm", "$12$ cm", "$6\\sqrt{2}$ cm"], answer: 3, solution: "1. AC adalah diagonal sisi pada persegi ABCD. 2. Panjang diagonal sisi $= s\\sqrt{2}$. 3. $AC = 6\\sqrt{2}$ cm." },
    { q: "Kubus ABCD.EFGH dengan rusuk 6 cm. Jarak titik A ke titik G adalah ...", options: ["$6\\sqrt{3}$ cm", "$6\\sqrt{2}$ cm", "$12$ cm", "$18$ cm"], answer: 0, solution: "1. AG adalah diagonal ruang kubus. 2. Panjang diagonal ruang $= s\\sqrt{3}$. 3. $AG = 6\\sqrt{3}$ cm." },
    { q: "Balok ABCD.EFGH dengan AB = 6 cm, BC = 8 cm, dan CG = 10 cm. Jarak titik A ke titik H adalah ...", options: ["$10$ cm", "$10\\sqrt{2}$ cm", "$14$ cm", "$20$ cm"], answer: 1, solution: "1. Tempatkan A(0,0,0) sehingga H(6,8,10). 2. $AH = \\sqrt{6^2+8^2+10^2} = \\sqrt{200}$. 3. $\\sqrt{200} = 10\\sqrt{2}$ cm." },
    { q: "Kubus ABCD.EFGH dengan rusuk 8 cm. Jarak titik B ke garis AC adalah ...", options: ["$8\\sqrt{2}$ cm", "$4$ cm", "$4\\sqrt{2}$ cm", "$8$ cm"], answer: 2, solution: "1. Proyeksi titik B pada diagonal AC adalah titik tengah AC. 2. Jarak $= \\frac{1}{2} \\times$ diagonal sisi $= \\frac{1}{2} \\times 8\\sqrt{2}$. 3. $= 4\\sqrt{2}$ cm." },
    { q: "Kubus ABCD.EFGH dengan rusuk 4 cm. Jarak titik E ke garis BD adalah ...", options: ["$4\\sqrt{3}$ cm", "$2\\sqrt{3}$ cm", "$4\\sqrt{2}$ cm", "$2\\sqrt{6}$ cm"], answer: 3, solution: "1. Ambil A(0,0,0) sehingga E(0,0,4), B(4,0,0), D(0,4,0). 2. $\\vec{BE} = (-4,0,4)$ dan vektor satuan arah BD $= \\frac{1}{\\sqrt{2}}(-1,1,0)$; besar hasil kali silangnya $= 4\\sqrt{3}$. 3. Jarak $= \\frac{4\\sqrt{3}}{\\sqrt{2}} = 2\\sqrt{6}$ cm." },
    { q: "Limas beraturan T.ABCD dengan alas persegi sisi 6 cm dan tinggi 4 cm. Jarak titik T ke garis BC adalah ...", options: ["$5$ cm", "$4$ cm", "$3$ cm", "$7$ cm"], answer: 0, solution: "1. Jarak O (pusat alas) ke garis BC $= \\frac{6}{2} = 3$ cm. 2. Jarak T ke BC $= \\sqrt{TO^2 + 3^2} = \\sqrt{16+9}$. 3. $= \\sqrt{25} = 5$ cm." },
    { q: "Kubus ABCD.EFGH dengan rusuk 6 cm. Jarak titik C ke bidang AFH adalah ...", options: ["$2\\sqrt{3}$ cm", "$4\\sqrt{3}$ cm", "$6\\sqrt{3}$ cm", "$3\\sqrt{3}$ cm"], answer: 1, solution: "1. Dengan A sebagai pusat koordinat, bidang AFH berpersamaan $x + y - z = 0$. 2. Jarak C(6,6,0) ke bidang: $\\frac{|6+6-0|}{\\sqrt{3}} = \\frac{12}{\\sqrt{3}}$. 3. $= 4\\sqrt{3}$ cm." },
    { q: "Kubus ABCD.EFGH dengan rusuk 9 cm. Jarak titik A ke bidang BDG adalah ...", options: ["$6\\sqrt{3}$ cm", "$9$ cm", "$3\\sqrt{3}$ cm", "$3\\sqrt{2}$ cm"], answer: 2, solution: "1. Bidang BDG berpersamaan $x + y - z = 9$. 2. Jarak A(0,0,0) ke bidang: $\\frac{|0+0-0-9|}{\\sqrt{3}} = \\frac{9}{\\sqrt{3}}$. 3. $= 3\\sqrt{3}$ cm." },
    { q: "Balok ABCD.EFGH dengan AB = 3 cm, AD = 4 cm, dan AE = 5 cm. Jarak titik B ke titik G adalah ...", options: ["$5$ cm", "$7$ cm", "$10$ cm", "$5\\sqrt{2}$ cm"], answer: 3, solution: "1. BG adalah diagonal ruang balok. 2. $BG = \\sqrt{AB^2+AD^2+AE^2} = \\sqrt{9+16+25} = \\sqrt{50}$. 3. $= 5\\sqrt{2}$ cm." },
    { q: "Limas beraturan T.ABCD dengan alas persegi sisi 8 cm dan tinggi 6 cm. Jarak titik A ke titik T adalah ...", options: ["$2\\sqrt{17}$ cm", "$10$ cm", "$8$ cm", "$6\\sqrt{2}$ cm"], answer: 0, solution: "1. Jarak A ke pusat alas O $= \\frac{8\\sqrt{2}}{2} = 4\\sqrt{2}$ cm. 2. $AT = \\sqrt{AO^2+TO^2} = \\sqrt{32+36} = \\sqrt{68}$. 3. $= 2\\sqrt{17}$ cm." },
    { q: "Kubus ABCD.EFGH dengan rusuk 10 cm. Jarak garis AB ke garis GH adalah ...", options: ["$10$ cm", "$10\\sqrt{2}$ cm", "$20$ cm", "$5\\sqrt{2}$ cm"], answer: 1, solution: "1. AB dan GH sejajar; AB terletak pada $y=0, z=0$ sedangkan GH pada $y=10, z=10$. 2. Jarak $= \\sqrt{(10-0)^2+(10-0)^2} = \\sqrt{200}$. 3. $= 10\\sqrt{2}$ cm." },
    { q: "Kubus ABCD.EFGH dengan rusuk 5 cm. Jarak garis EF ke bidang ABCD adalah ...", options: ["$5\\sqrt{2}$ cm", "$10$ cm", "$5$ cm", "$0$ cm"], answer: 2, solution: "1. Garis EF sejajar dengan bidang ABCD. 2. Jaraknya sama dengan selisih tinggi, yaitu rusuk kubus. 3. $= 5$ cm." },
    { q: "Kubus ABCD.EFGH dengan rusuk 6 cm. Jarak titik H ke garis AC adalah ...", options: ["$6\\sqrt{3}$ cm", "$3\\sqrt{3}$ cm", "$6$ cm", "$3\\sqrt{6}$ cm"], answer: 3, solution: "1. Ambil A(0,0,0), C(6,6,0), H(0,6,6); vektor satuan arah AC $= \\frac{1}{\\sqrt{2}}(1,1,0)$. 2. $\\vec{AH} = (0,6,6)$; besar hasil kali silang $\\vec{AH}$ dengan arah AC $= 6\\sqrt{3}$. 3. Jarak $= \\frac{6\\sqrt{3}}{\\sqrt{2}} = 3\\sqrt{6}$ cm." },
    { q: "Balok ABCD.EFGH dengan AB = 8 cm, BC = 6 cm, dan CG = 4 cm. Jarak titik E ke garis CG adalah ...", options: ["$10$ cm", "$8$ cm", "$6$ cm", "$4$ cm"], answer: 0, solution: "1. Garis CG tegak lurus bidang alas di titik C. 2. Jarak E ke garis CG sama dengan jarak E ke C, yaitu $\\sqrt{AB^2+BC^2}$. 3. $= \\sqrt{64+36} = 10$ cm." },
    { q: "Pada kubus ABCD.EFGH, besar sudut antara garis AC dan garis AF adalah ...", options: ["$45^\\circ$", "$60^\\circ$", "$90^\\circ$", "$30^\\circ$"], answer: 1, solution: "1. AC dan AF adalah diagonal sisi yang bertemu di A, dengan $AC = AF = CF$. 2. Segitiga ACF merupakan segitiga sama sisi. 3. Setiap sudutnya $60^\\circ$." },
    { q: "Pada kubus ABCD.EFGH, besar sudut antara garis AH dan garis DE adalah ...", options: ["$60^\\circ$", "$45^\\circ$", "$90^\\circ$", "$0^\\circ$"], answer: 2, solution: "1. Vektor arah AH $= (0,1,1)$ dan vektor arah DE $= (0,-1,1)$. 2. Hasil kali titiknya $= 0(0) + 1(-1) + 1(1) = 0$. 3. Karena saling tegak lurus, sudutnya $90^\\circ$." },
    { q: "Pada kubus ABCD.EFGH, besar sudut antara garis AF dan garis BG adalah ...", options: ["$90^\\circ$", "$45^\\circ$", "$30^\\circ$", "$60^\\circ$"], answer: 3, solution: "1. Vektor arah AF $= (1,0,1)$ dan vektor arah BG $= (0,1,1)$ (dengan rusuk $= 1$). 2. $\\cos \\theta = \\frac{0+0+1}{\\sqrt{2}\\sqrt{2}} = \\frac{1}{2}$. 3. $\\theta = 60^\\circ$." },
    { q: "Limas beraturan T.ABCD dengan alas persegi sisi 6 cm dan tinggi $3\\sqrt{2}$ cm. Besar sudut antara rusuk TA dan bidang alas adalah ...", options: ["$45^\\circ$", "$30^\\circ$", "$60^\\circ$", "$90^\\circ$"], answer: 0, solution: "1. Proyeksi TA pada bidang alas adalah AO dengan $AO = \\frac{6\\sqrt{2}}{2} = 3\\sqrt{2}$ cm. 2. $\\tan \\theta = \\frac{TO}{AO} = \\frac{3\\sqrt{2}}{3\\sqrt{2}} = 1$. 3. $\\theta = 45^\\circ$." },
    { q: "Limas beraturan T.ABCD dengan alas persegi sisi 8 cm dan tinggi 4 cm. Besar sudut antara bidang TBC dan bidang alas ABCD adalah ...", options: ["$30^\\circ$", "$45^\\circ$", "$60^\\circ$", "$37^\\circ$"], answer: 1, solution: "1. Sudut antara kedua bidang diukur melalui garis tinggi segitiga TBC yang tegak lurus BC. 2. $\\tan \\theta = \\frac{\\text{tinggi limas}}{\\text{setengah sisi alas}} = \\frac{4}{4} = 1$. 3. $\\theta = 45^\\circ$." },
    { q: "Pada kubus ABCD.EFGH, besar sudut antara bidang diagonal ABGH dan bidang ABCD adalah ...", options: ["$90^\\circ$", "$60^\\circ$", "$45^\\circ$", "$30^\\circ$"], answer: 2, solution: "1. Vektor normal bidang ABGH $= (0,-1,1)$ dan normal bidang ABCD $= (0,0,1)$. 2. $\\cos \\theta = \\frac{1}{\\sqrt{2}}$. 3. $\\theta = 45^\\circ$." },
    { q: "Pada kubus ABCD.EFGH, besar sudut antara garis BE dan bidang CDHG adalah ...", options: ["$30^\\circ$", "$60^\\circ$", "$90^\\circ$", "$45^\\circ$"], answer: 3, solution: "1. Jarak titik B ke bidang CDHG $= s$ (rusuk) dan panjang $BE = s\\sqrt{2}$. 2. $\\sin \\theta = \\frac{s}{s\\sqrt{2}} = \\frac{\\sqrt{2}}{2}$. 3. $\\theta = 45^\\circ$." },
    { q: "Volume kubus dengan panjang rusuk 9 cm adalah ...", options: ["$729$ cm$^3$", "$486$ cm$^3$", "$81$ cm$^3$", "$243$ cm$^3$"], answer: 0, solution: "1. $V = s^3$. 2. $V = 9^3$. 3. $= 729$ cm$^3$." },
    { q: "Volume balok dengan ukuran 6 cm $\\times$ 8 cm $\\times$ 10 cm adalah ...", options: ["$240$ cm$^3$", "$480$ cm$^3$", "$960$ cm$^3$", "$180$ cm$^3$"], answer: 1, solution: "1. $V = p \\times l \\times t$. 2. $V = 6 \\times 8 \\times 10$. 3. $= 480$ cm$^3$." },
    { q: "Volume limas segiempat beraturan dengan alas persegi sisi 10 cm dan tinggi 12 cm adalah ...", options: ["$1.200$ cm$^3$", "$600$ cm$^3$", "$400$ cm$^3$", "$300$ cm$^3$"], answer: 2, solution: "1. $V = \\frac{1}{3} \\times$ luas alas $\\times$ tinggi. 2. $V = \\frac{1}{3} \\times 100 \\times 12$. 3. $= 400$ cm$^3$." },
    { q: "Volume prisma tegak segitiga dengan alas segitiga siku-siku (sisi tegaknya 6 cm dan 8 cm) dan tinggi prisma 10 cm adalah ...", options: ["$480$ cm$^3$", "$120$ cm$^3$", "$360$ cm$^3$", "$240$ cm$^3$"], answer: 3, solution: "1. Luas alas $= \\frac{1}{2} \\times 6 \\times 8 = 24$. 2. $V = $ luas alas $\\times$ tinggi prisma $= 24 \\times 10$. 3. $= 240$ cm$^3$." },
    { q: "Banyak rusuk pada prisma segienam beraturan adalah ...", options: ["$18$", "$12$", "$24$", "$36$"], answer: 0, solution: "1. Prisma segi-$n$ memiliki $3n$ rusuk. 2. Untuk segienam, $n = 6$. 3. Banyak rusuk $= 3 \\times 6 = 18$." }
  ]
};
